insert into public.exercises
  (slug, name, tier, category, muscle_primary, muscle_secondary, emphasis,
   one_rm_factor, unit, secs, video_id, why, cues, equipment)
values
('flat-barbell-press', 'Flat Barbell Press', 'full_gym', 'compound', array['pec_major_sternal']::text[], array['anterior_delt','tricep']::text[], array['chest','push','upper_body']::text[], 1, 'reps', null, null, 'Maximum mechanical advantage for pec major sternal fibres. Highest absolute load ceiling of all pressing variants. The gold standard for measuring horizontal push capacity.', array['Retract and depress scapula into bench','Bar path: lower chest at bottom, above lower pec at lockout','Drive heels into floor throughout','Full lockout — do not stop short']::text[], 'barbell'),
('db-bench-press', 'DB Bench Press', 'hotel_gym', 'compound', array['pec_major_sternal']::text[], array['anterior_delt','tricep']::text[], array['chest','push','upper_body']::text[], 0.88, 'reps', null, 'VmB1G1K7v94', 'Dumbbells demand more stabiliser recruitment than barbell — serratus anterior and rotator cuff activate heavily to control the free path. Each hand works independently, preventing dominant-side compensation.', array['Neutral wrist, soft elbow lockout','Lower until upper arms parallel to floor','Slight arch — ribs up, shoulders back','Squeeze at the top for one count']::text[], 'dumbbell'),
('incline-db-press', 'Incline DB Press', 'hotel_gym', 'compound', array['pec_major_clavicular']::text[], array['anterior_delt','tricep']::text[], array['chest','push','upper_body']::text[], 0.86, 'reps', null, null, 'At 30–45° the clavicular pec head dominates EMG activity. DB variation adds a deeper bottom-position stretch versus barbell, increasing time under tension through full ROM. Evidence-informed progression from flat DB — same implement, adds upper-pec angle.', array['Set bench to 30° — not steeper','Elbows at 60–70° from torso, not flared to 90°','Full stretch at bottom without shoulder impingement','Drive up and slightly in — a slight arc, not straight up']::text[], 'dumbbell'),
('low-incline-barbell-press', 'Low Incline Barbell Press', 'full_gym', 'compound', array['pec_major_clavicular']::text[], array['anterior_delt','tricep']::text[], array['chest','push','upper_body']::text[], 0.93, 'reps', null, 'DbFgADa2PL8', '30° is the mechanically superior angle for most lifters — maximises clavicular pec recruitment while keeping the subacromial space open. EMG studies confirm 30–45° produces peak upper-chest activation.', array['Retract scapula','Lower to mid-chest','Drive through heels','Full lockout at top']::text[], 'barbell'),
('high-incline-barbell-press', 'High Incline Barbell Press', 'full_gym', 'compound', array['pec_major_clavicular','anterior_delt']::text[], array['tricep']::text[], array['chest','shoulders','push','upper_body']::text[], 0.8, 'reps', null, null, 'At 45–60° the load shifts significantly toward the anterior deltoid — useful for shoulder-emphasis programming. Expect ~20% less pec activation than at 30°. Best as a periodisation variation rather than a primary chest builder.', array['Keep elbows directly under wrists','Scapula retracted throughout','Do not touch chest — stop one inch above','Control the descent; eccentric under full tension']::text[], 'barbell'),
('decline-barbell-press', 'Decline Barbell Press', 'full_gym', 'compound', array['pec_major_sternal']::text[], array['tricep']::text[], array['chest','push','upper_body']::text[], 1.07, 'reps', null, null, 'The decline angle puts pec major sternal fibres in their strongest mechanical position — most lifters press 5–10% more here than flat. Lower pec volume is chronically undertrained; decline closes that gap.', array['Secure ankles before unracking','Bar to lower chest (below nipple line)','Wrists stacked over elbows','Full lockout — triceps contribute heavily here']::text[], 'barbell'),
('decline-db-press', 'Decline DB Press', 'hotel_gym', 'compound', array['pec_major_sternal']::text[], array['tricep']::text[], array['chest','push','upper_body']::text[], 0.94, 'reps', null, null, 'Lower-pec emphasis of decline barbell with greater ROM and unilateral loading. Useful when a decline bench is available but no barbell — or when adding angle variation after flat DB mastery.', array['Secure ankles; dumbbells on thighs before lying back','Lower to lower chest with control','Neutral wrist throughout','Squeeze at top — ROM is slightly shorter than flat']::text[], 'dumbbell'),
('close-grip-barbell-press', 'Close-Grip Barbell Press', 'full_gym', 'compound', array['tricep']::text[], array['pec_major_sternal','anterior_delt']::text[], array['triceps','chest','push','upper_body']::text[], 0.85, 'reps', null, null, 'Shoulder-width grip shifts load away from pec onto triceps — specifically the long head. A compound movement for tricep mass that outperforms any isolation exercise for pure size development.', array['Hands shoulder-width — not too narrow (wrist stress)','Elbows stay tucked close to torso','Lower to lower chest/upper abdomen','Lock out at the top through the triceps']::text[], 'barbell'),
('dips', 'Dips', 'hotel_gym', 'compound', array['pec_major_sternal','tricep']::text[], array['anterior_delt']::text[], array['chest','triceps','push','upper_body']::text[], 0.85, 'reps', null, null, 'Among the highest pec major EMG outputs of any bodyweight pressing movement. Forward lean increases chest activation; upright torso shifts load to triceps. Add weight via belt or held dumbbell to progress.', array['Lean forward slightly for chest emphasis','Lower until upper arms parallel to floor','Do not flare elbows past 45°','Full lockout at top']::text[], 'bodyweight'),
('push-up', 'Push-Up', 'home', 'compound', array['pec_major_sternal']::text[], array['tricep','anterior_delt','serratus_anterior']::text[], array['chest','push','upper_body']::text[], 0.6, 'reps', null, 'IODxDxX7oi4', 'More serratus anterior activation than any barbell or dumbbell pressing variant. Serratus anchors the scapula against the rib cage — essential for shoulder health and overhead performance. Rings or a ball add instability for advanced overload.', array['Straight body from heels to head — no hip sag','Hands just outside shoulder-width','Elbows at 45°, not flared to 90°','Full lockout; protract scapula at top (push the floor away)']::text[], 'bodyweight'),
('cable-low-to-high-fly', 'Cable Low-to-High Fly', 'full_gym', 'isolation', array['pec_major_clavicular']::text[], array['anterior_delt']::text[], array['chest','push','upper_body']::text[], null, 'reps', null, 'pYcpY20QaE8', 'Cable maintains constant tension through the full arc — dumbbells go slack at the top. Low-to-high arc preferentially loads the clavicular pec fibres in the shortened position where they produce peak force.', array['Set cables at ankle height','Slight forward lean','Soft elbows — this is not a press','Squeeze at the top like hugging a barrel']::text[], 'cable'),
('db-fly', 'DB Fly', 'hotel_gym', 'isolation', array['pec_major_sternal']::text[], array['anterior_delt']::text[], array['chest','push','upper_body']::text[], null, 'reps', null, null, 'The chest isolation when no cable stack is available. The deep bottom-position stretch loads the sternal pec fibres in the lengthened position, where the strongest hypertrophy stimulus occurs.', array['Lie flat, dumbbells above chest, palms facing','Soft elbow bend held constant — open at the shoulder, not the elbow','Lower until a deep pec stretch, upper arms near parallel to floor','Squeeze back up along the same arc; do not press']::text[], 'dumbbell'),
('band-chest-fly', 'Band Chest Fly', 'home', 'isolation', array['pec_major_sternal']::text[], array['anterior_delt']::text[], array['chest','push','upper_body']::text[], null, 'reps', null, null, 'Band tension rises through the arc, peaking in the shortened position where the pec produces most force — the inverse of a dumbbell fly. Pure chest isolation needing only a band and an anchor.', array['Anchor the band behind you at chest height','Soft elbows, hug forward until hands meet','Squeeze the pecs hard for one count','Resist the band back to a full stretch']::text[], 'band'),
('machine-chest-press', 'Machine Chest Press', 'full_gym', 'compound', array['pec_major_sternal']::text[], array['anterior_delt','tricep']::text[], array['chest','push','upper_body']::text[], 0.9, 'reps', null, null, 'The fixed path lets a lifter push chest to failure safely without a spotter — the machine catches the load, so it is the ideal way to train the sternal pec close to failure late in a session. Converging handles add a squeeze at lockout a barbell cannot.', array['Set the seat so the handles line up with mid-chest','Retract and depress the shoulder blades against the pad','Press to full extension without shrugging','Control the return — do not let the stack pull the arms back fast']::text[], 'machine'),
('pec-deck', 'Pec Deck', 'full_gym', 'isolation', array['pec_major_sternal']::text[], array['anterior_delt']::text[], array['chest','push','upper_body']::text[], null, 'reps', null, null, 'Pure pec isolation on a fixed arc — the machine removes all stabiliser demand so the sternal fibres take the entire load through a constant-tension horizontal adduction. Easier to load progressively and safer at failure than a dumbbell fly.', array['Elbows on the pads (or hands on the handles) at chest height','Drive the pads together by squeezing the chest — not the arms','Pause one count when the pads meet','Open slowly to a full stretch without letting the plates touch down']::text[], 'machine'),
('high-to-low-cable-fly', 'High-to-Low Cable Fly', 'full_gym', 'isolation', array['pec_major_sternal']::text[], array['anterior_delt']::text[], array['chest','push','upper_body']::text[], null, 'reps', null, null, 'The downward arc from high pulleys preferentially loads the lower and sternal pec fibres in the shortened position — the mirror image of the low-to-high fly. Cables hold constant tension through the full sweep where a dumbbell goes slack at the top.', array['Set both pulleys above head height','Step forward into a slight lean; soft constant elbow bend','Sweep the hands down and together toward the belt line','Squeeze where the hands cross; resist back up along the same arc']::text[], 'cable'),
('incline-db-fly', 'Incline DB Fly', 'hotel_gym', 'isolation', array['pec_major_clavicular']::text[], array['anterior_delt']::text[], array['chest','push','upper_body']::text[], null, 'reps', null, null, 'Isolates the clavicular (upper) pec in a deep stretched position — the incline angle plus the fly path loads the upper fibres where hypertrophy signalling is strongest. The chest isolation for upper-pec bias when only dumbbells are available.', array['Set the bench to 30°, dumbbells above the upper chest, palms facing','Hold a soft, fixed elbow bend — open at the shoulder, not the elbow','Lower until a deep upper-pec stretch, upper arms near parallel to the floor','Squeeze back up along the same arc; do not press']::text[], 'dumbbell'),
('alternating-db-bench-press', 'Alternating DB Bench Press', 'hotel_gym', 'compound', array['pec_major_sternal']::text[], array['anterior_delt','tricep','core']::text[], array['chest','push','upper_body']::text[], 0.85, 'reps', null, null, 'Pressing one arm at a time keeps the working pec under constant tension while the opposite arm holds an isometric at lockout — extending time under tension and forcing the core to resist rotation. An excellent burnout finisher and a skill-appropriate alternative when a lifter wants maximum unilateral fatigue without a spotter.', array['Both dumbbells locked out over the chest to start','Lower and press one side while the other holds at the top','Keep the hips and torso flat — resist the pull to rotate','Alternate under control; do not let the resting arm drift or bend']::text[], 'dumbbell'),
('alternating-incline-db-press', 'Alternating Incline DB Press', 'hotel_gym', 'compound', array['pec_major_clavicular']::text[], array['anterior_delt','tricep','core']::text[], array['chest','push','upper_body']::text[], 0.83, 'reps', null, null, 'The alternating tempo doubles time under tension on the upper pec while the held arm braces isometrically and the core resists rotation — an upper-chest burnout variant. Best programmed after the primary press when the goal is to accumulate fatigue on the clavicular fibres.', array['Bench at 30°, both dumbbells locked out to start','Press one side at a time; the other holds at full extension','Keep elbows at ~60–70° from the torso, not flared','Alternate slowly and evenly — control both the lift and the hold']::text[], 'dumbbell'),
('db-floor-press', 'DB Floor Press', 'hotel_gym', 'compound', array['pec_major_sternal']::text[], array['tricep','anterior_delt']::text[], array['chest','push','upper_body']::text[], 0.82, 'reps', null, null, 'The floor stops the elbows at roughly 90°, cutting the bottom range that stresses the shoulder — the most shoulder-friendly heavy pressing option and a strong tricep-lockout builder. Needs only dumbbells and floor space, so it travels anywhere.', array['Lie on the floor, knees bent, dumbbells over the chest','Lower until the upper arms rest lightly on the floor — do not bounce','Pause briefly, then press back to full lockout','Keep the wrists stacked over the elbows throughout']::text[], 'dumbbell'),
('cable-chest-press', 'Cable Chest Press', 'full_gym', 'compound', array['pec_major_sternal']::text[], array['anterior_delt','tricep']::text[], array['chest','push','upper_body']::text[], 0.8, 'reps', null, null, 'Standing cable pressing holds constant tension through the whole stroke and lets the hands converge at lockout for a hard chest squeeze a barbell cannot match — while the standing position adds an anti-rotation core demand. A joint-friendly press with a peak-contraction advantage.', array['Set both pulleys at chest height, staggered stance for balance','Press the handles forward and together to a squeeze at lockout','Keep the torso upright and braced — do not lean into the press','Control the return; keep constant tension, do not let the stack rest']::text[], 'cable'),
('squeeze-press', 'Squeeze Press', 'hotel_gym', 'compound', array['pec_major_sternal']::text[], array['anterior_delt','tricep']::text[], array['chest','push','upper_body']::text[], 0.75, 'reps', null, null, 'Pressing two dumbbells mashed together the whole way forces continuous horizontal adduction — keeping the inner pec fibres maximally contracted through the entire rep. A pump-and-squeeze variation that hits the mid-chest line dumbbells otherwise miss.', array['Press two dumbbells together with a neutral grip, hard the whole time','Push them straight up while crushing them inward','Squeeze the chest hard at the top for a full count','Lower under control without letting the dumbbells separate']::text[], 'dumbbell'),
('smith-machine-bench-press', 'Smith Machine Bench Press', 'full_gym', 'compound', array['pec_major_sternal']::text[], array['anterior_delt','tricep']::text[], array['chest','push','upper_body']::text[], 0.92, 'reps', null, null, 'The fixed vertical bar path removes the balance demand, letting a lifter push chest close to failure safely and even without a spotter — ideal for overloading the sternal pec late in a session or for newer lifters still grooving the press pattern. Ranked below the free-weight barbell presses: a guided machine press is an assistance movement, not a primary prescription over free weights.', array['Set the bench so the bar lines up with the lower chest','Retract and depress the shoulder blades into the bench','Lower to a light touch on the chest; press to full lockout','Rotate the wrists to unrack/rerack the safety hooks between sets']::text[], 'machine'),
('arnold-press', 'Arnold Press', 'hotel_gym', 'compound', array['anterior_delt','lateral_delt']::text[], array['posterior_delt','tricep']::text[], array['shoulders','push','upper_body']::text[], null, 'reps', null, 'hmEGkvxmCl0', 'The supinated-to-pronated rotation is the only shoulder press that recruits all three delt heads in a single movement arc. The rotation sweeps anterior → lateral → posterior fibers across the full arc.', array['Start with palms facing you, elbows at 90°','Rotate outward as you press — palms face forward at top','Do not rush the rotation — the arc is the exercise','Control the return rotation — same path, reversed']::text[], 'dumbbell'),
('barbell-ohp', 'Barbell Overhead Press', 'full_gym', 'compound', array['anterior_delt','lateral_delt']::text[], array['tricep','upper_trap','serratus_anterior']::text[], array['shoulders','push','upper_body']::text[], null, 'reps', null, null, 'The standing barbell OHP builds total overhead strength plus forces core stability, scapular upward rotation, and upper trap development that seated variations miss. Pound-for-pound the most demanding shoulder compound.', array['Start bar at collarbone, wrists straight','Press up and slightly back — bar travels in a slight arc','Lock out overhead with ears between arms (full shoulder flexion)','Brace the core as hard as a squat']::text[], 'barbell'),
('db-shoulder-press', 'DB Shoulder Press', 'hotel_gym', 'compound', array['anterior_delt','lateral_delt']::text[], array['tricep']::text[], array['shoulders','push','upper_body']::text[], null, 'reps', null, null, 'Dumbbell overhead pressing allows each shoulder to move in its natural arc rather than locked in a barbell path — critical for lifters with shoulder asymmetries or impingement history. Unilateral DB press identifies side-to-side deficits.', array['Neutral or pronated grip — pronated is standard','Slight forward lean from hip','Press up to full extension without shrugging','Lower to 90° at elbows — do not go below parallel']::text[], 'dumbbell'),
('push-press', 'Push Press', 'full_gym', 'compound', array['anterior_delt','lateral_delt']::text[], array['tricep','quad','glute_max','upper_trap']::text[], array['shoulders','push','upper_body','full_body']::text[], null, 'reps', null, null, 'The leg drive in push press allows 10–15% heavier loads than a strict OHP, overloading the deltoids in the top-range lock-out position. Develops explosive pressing power and full-body coordination simultaneously.', array['Dip: slight knee bend (~20°), torso stays upright','Drive up from the legs explosively','Press overhead from leg momentum — continue pressing to lockout','Lower under control — do not drop the bar']::text[], 'barbell'),
('z-press', 'Z-Press', 'full_gym', 'compound', array['anterior_delt','lateral_delt']::text[], array['tricep','core','hip_flexor']::text[], array['shoulders','push','upper_body','core']::text[], null, 'reps', null, null, 'Pressing from a seated-on-the-floor position eliminates any leg drive and forces the core to stabilise the spine under overhead load without a back support. Any forward lean or spinal flexion immediately fails the rep — the strictest shoulder press that exists.', array['Sit on the floor, legs straight out, torso absolutely vertical','Press the bar with zero leg involvement — if you lean back, reduce load','Full lockout overhead — ears between arms','This is a humbling movement — use 60–70% of your standing OHP']::text[], 'barbell'),
('db-lateral-raise', 'DB Lateral Raise', 'hotel_gym', 'isolation', array['lateral_delt']::text[], array[]::text[], array['shoulders','upper_body']::text[], null, 'reps', null, null, 'The lateral delt is the primary muscle responsible for shoulder width — it is barely stimulated by pressing movements. Lateral raises are non-negotiable for building the "boulder shoulder" look. DB version is available everywhere.', array['Slight forward lean and slight elbow bend','Lead with the pinky — external rotation keeps lateral delt primary','Stop at shoulder height — above that recruits the trap, not the delt','Slow the eccentric: 3-second lower for maximum stimulus']::text[], 'dumbbell'),
('cable-lateral-raise', 'Cable Lateral Raise', 'full_gym', 'isolation', array['lateral_delt']::text[], array[]::text[], array['shoulders','upper_body']::text[], null, 'reps', null, '8IHpPAAZTCk', 'Cable maintains constant tension on the lateral delt through the full range — dumbbells have zero tension at the bottom. Cross-body cable also adds horizontal abduction demand at the top that vertical DB raises cannot replicate.', array['Cable at ankle height, work arm across the body','Slight lean away from cable stack','Lead with the pinky for external rotation','Stop at shoulder height — above that becomes trap']::text[], 'cable'),
('lateral-raise-machine', 'Lateral Raise Machine', 'full_gym', 'isolation', array['lateral_delt']::text[], array[]::text[], array['shoulders','upper_body']::text[], null, 'reps', null, null, 'Machine lateral raises provide guided path and bilateral load — useful when cheat-repping with dumbbells becomes a problem. The fixed arc eliminates the temptation to swing and produces clean lateral delt isolation.', array['Adjust pad to sit against inner elbow, not the wrist','Keep the torso tall and still throughout','Drive elbows up to shoulder height — do not go higher','Controlled return all the way to the bottom']::text[], 'machine'),
('single-arm-cable-lateral-raise', 'Single-Arm Cable Lateral Raise', 'full_gym', 'isolation', array['lateral_delt']::text[], array[]::text[], array['shoulders','upper_body']::text[], null, 'reps', null, null, 'Unilateral cable lateral raise lets you dedicate full focus to each side independently — identifies and corrects lateral delt asymmetries that bilateral work masks. The bottom-of-ROM constant tension is the same as bilateral cable.', array['Cable at ankle height, opposite hand on the stack for stability','Raise in a pure lateral arc to shoulder height','Pause for 1 count at peak — actively hold against the cable pull','Lower slowly with full resistance from cable']::text[], 'cable'),
('db-front-raise', 'DB Front Raise', 'hotel_gym', 'isolation', array['anterior_delt']::text[], array['pec_major_clavicular']::text[], array['shoulders','push','upper_body']::text[], null, 'reps', null, null, 'Front raises train the anterior delt in a lengthened position — different from the shortened position stressed by pressing. Use sparingly: anterior delt is heavily loaded by all pressing movements and can become overdeveloped relative to lateral and posterior heads.', array['Arms start at thigh level, palms facing down','Raise to shoulder height — stop there','Keep a slight elbow bend throughout','Alternate arms or raise both; control the eccentric']::text[], 'dumbbell'),
('cable-front-raise', 'Cable Front Raise', 'full_gym', 'isolation', array['anterior_delt']::text[], array['pec_major_clavicular']::text[], array['shoulders','push','upper_body']::text[], null, 'reps', null, null, 'Cable provides constant tension at the bottom of the front raise — where dumbbells are nearly tension-free. Useful as a finishing exercise after heavy pressing when the anterior delt needs targeted volume.', array['Cable at ankle height, facing away from stack','Raise the arm straight in front to shoulder height','Keep slight elbow bend throughout','Slow eccentric — resist the cable on the way down']::text[], 'cable'),
('face-pull', 'Face Pull', 'full_gym', 'isolation', array['posterior_delt','rhomboid','external_rotator']::text[], array[]::text[], array['shoulders','back','pull','upper_body']::text[], null, 'reps', null, 'eIq5CB9JfKE', 'Face pulls are the single best exercise for posterior delt and external rotation strength — both chronically undertrained in push-dominant programs. Every pressing session without face pull counterbalancing is a shoulder injury accumulating.', array['Cable at eye height or above with rope attachment','Pull to forehead level — elbows stay high, not dropping','Externally rotate hard at peak (hands point to ceiling)','Light weight, high rep — this is shoulder health, not ego work']::text[], 'cable'),
('rear-delt-fly', 'Rear Delt Fly', 'hotel_gym', 'isolation', array['posterior_delt','rhomboid']::text[], array[]::text[], array['shoulders','back','pull','upper_body']::text[], null, 'reps', null, null, 'Posterior delt is the most undertrained muscle in lifters. Weak posterior delts drive forward shoulder posture, rotator cuff injuries, and limit pressing performance. Can be done anywhere with dumbbells — no cable required.', array['Hinge at hips 45°, chest toward floor','Lead with the elbow, not the hand','Stop at shoulder height — slight elbow bend is fine','Squeeze for one count at peak; lower with control']::text[], 'dumbbell'),
('prone-y-raise', 'Prone Y-Raise', 'home', 'isolation', array['lower_trap','posterior_delt']::text[], array['rhomboid','supraspinatus']::text[], array['shoulders','back','upper_body']::text[], null, 'reps', null, null, 'The Y-raise on a prone position trains the lower trapezius — one of the most critical muscles for scapular upward rotation and long-term shoulder health. Deficient lower trap is implicated in impingement syndrome and rotator cuff injuries.', array['Lie face down on floor or incline bench','Arms in a Y shape above head (palms down)','Lift arms by squeezing shoulder blades together AND down','Hold 2 seconds at peak; slow lower — use very light or no weight']::text[], 'bodyweight'),
('prone-t-raise', 'Prone T-Raise', 'home', 'isolation', array['posterior_delt','middle_trap']::text[], array['rhomboid']::text[], array['shoulders','back','upper_body']::text[], null, 'reps', null, null, 'The T-raise targets the middle trapezius and posterior delt in a no-equipment setting. Alongside Y-raise, it completes the upper back health trifecta.', array['Lie face down; arms straight out to the sides (T position)','Thumbs pointing up (external rotation)','Lift arms by squeezing shoulder blades — height matters less than contraction','Lower slowly; repeat with full range of motion']::text[], 'bodyweight'),
('upright-row', 'Upright Row', 'full_gym', 'compound', array['lateral_delt','upper_trap']::text[], array['bicep','posterior_delt']::text[], array['shoulders','upper_body']::text[], null, 'reps', null, null, 'The upright row is one of the few compound shoulder exercises — it loads lateral delt AND upper trap simultaneously. Wide grip (outside shoulder-width) reduces shoulder impingement risk and shifts load toward lateral delt.', array['Wide grip: hands just outside shoulder-width','Pull bar up toward chin — elbows lead and rise above wrists','Stop when hands reach lower chest height — no higher','Lower under control; do not drop the bar']::text[], 'barbell'),
('cable-upright-row', 'Cable Upright Row', 'full_gym', 'compound', array['lateral_delt','upper_trap']::text[], array['bicep']::text[], array['shoulders','upper_body']::text[], null, 'reps', null, null, 'Cable version of the upright row with constant tension through the full ROM — particularly useful at the bottom of the movement where barbell tension is low. Attach a wide bar or EZ-bar to keep the shoulder-friendly wide grip.', array['Set cable at floor level, wide grip bar attachment','Pull up toward chin, elbows lead','Do not pull above lower chest level — protect AC joint','Slow the eccentric; the cable makes it easy to cheat on the way down']::text[], 'cable'),
('band-lateral-raise', 'Band Lateral Raise', 'home', 'isolation', array['lateral_delt']::text[], array[]::text[], array['shoulders','upper_body']::text[], null, 'reps', null, null, 'Band resistance profile is the inverse of dumbbell — it is hardest at the top (shoulder height) where lateral delt produces its peak force. This makes bands uniquely effective for lateral delt compared to dumbbells which get easy at the top.', array['Stand on the band, one or both ends in hand','Lead with the pinky (external rotation)','Drive to shoulder height against increasing band resistance','Lower slowly — band still provides resistance on the way down']::text[], 'band'),
('landmine-press', 'Landmine Press', 'full_gym', 'compound', array['anterior_delt','upper_pec']::text[], array['tricep','serratus_anterior']::text[], array['shoulders','chest','push','upper_body']::text[], null, 'reps', null, null, 'The landmine arc is dictated by physics, not a fixed track — the most shoulder-friendly pressing option for people with impingement or AC joint issues. The arc also trains shoulder flexion through a uniquely functional ROM.', array['One hand on end of bar; stand at 45° to anchor','Press in an arc from chest height to eye level','Keep elbow in tight to body throughout','Rotate trunk slightly as you press for full shoulder flexion']::text[], 'barbell'),
('shrug-barbell', 'Barbell Shrug', 'full_gym', 'isolation', array['upper_trap']::text[], array[]::text[], array['shoulders','upper_body']::text[], null, 'reps', null, null, 'Upper trapezius training matters for shoulder aesthetics and neck posture. Heavy shrugs — not the light prehab variety — are the most direct stimulus for upper trap mass.', array['Straight arms throughout — do not bend the elbows','Shrug straight UP — not rolling the shoulders (which can damage AC joint)','Hold at peak for 1 second','Lower fully — a full stretch at the bottom matters']::text[], 'barbell'),
('machine-shoulder-press', 'Machine Shoulder Press', 'full_gym', 'compound', array['anterior_delt','lateral_delt']::text[], array['tricep']::text[], array['shoulders','push','upper_body']::text[], null, 'reps', null, null, 'The guided vertical path lets a lifter overload the delts near failure without a spotter or the balance demand of free weights — ideal for driving overhead pressing volume when the stabilisers are already fatigued. Back support removes the core limitation of standing presses.', array['Set the seat so the handles start at shoulder height','Back flat against the pad, ribs down — do not arch to press','Press to full extension without locking harshly','Lower under control to a 90° elbow — do not crash the stack']::text[], 'machine'),
('reverse-pec-deck', 'Reverse Pec Deck', 'full_gym', 'isolation', array['posterior_delt']::text[], array['rhomboid','middle_trap']::text[], array['shoulders','back','pull','upper_body']::text[], null, 'reps', null, null, 'The most consistent posterior-delt isolation in any gym — the fixed arc keeps tension squarely on the rear delt through horizontal abduction, without the momentum and hinge-cheating that dumbbell rear flyes invite. Directly counters the forward-shoulder posture pressing builds.', array['Chest against the pad, handles at shoulder height','Lead with the elbows, driving the hands apart and back','Squeeze the shoulder blades together at the peak','Control the return; keep a soft, fixed elbow bend throughout']::text[], 'machine'),
('db-shrug', 'DB Shrug', 'hotel_gym', 'isolation', array['upper_trap']::text[], array[]::text[], array['shoulders','upper_body']::text[], null, 'reps', null, null, 'Dumbbells let the traps shrug straight up with the load hanging at the sides — a cleaner line of pull than a barbell held in front, and available anywhere a pair of dumbbells is. The direct stimulus for upper-trap mass and a fuller yoke.', array['Dumbbells at the sides, arms straight, shoulders relaxed to start','Shrug straight up toward the ears — do not roll the shoulders','Hold the top squeeze for one count','Lower to a full stretch at the bottom before the next rep']::text[], 'dumbbell'),
('band-shrug', 'Band Shrug', 'home', 'isolation', array['upper_trap']::text[], array[]::text[], array['shoulders','upper_body']::text[], null, 'reps', null, null, 'Same straight-arm elevation pattern as a barbell or DB shrug — the direct stimulus for upper-trap mass — using a band anchored under both feet so the resistance rises through the pull, needing no equipment beyond a band.', array['Stand on the band with both feet, one handle in each hand','Arms straight throughout — do not bend the elbows','Shrug straight UP toward the ears — do not roll the shoulders','Hold the top squeeze for one count, then lower to a full stretch']::text[], 'band'),
('alternating-db-shoulder-press', 'Alternating DB Shoulder Press', 'hotel_gym', 'compound', array['anterior_delt','lateral_delt']::text[], array['tricep','core']::text[], array['shoulders','push','upper_body']::text[], null, 'reps', null, null, 'Pressing one dumbbell at a time keeps the working delt under longer tension while the held arm braces overhead and the core resists the offset load leaning it sideways — an anti-lateral-flexion demand a bilateral press never creates. A great burnout and core-integration overhead variant.', array['Both dumbbells at shoulder height to start','Press one to full lockout while the other stays racked at the shoulder','Keep the torso vertical — do not lean away from the pressing side','Alternate under control; brace the abs and glutes throughout']::text[], 'dumbbell'),
('seated-db-shoulder-press', 'Seated DB Shoulder Press', 'hotel_gym', 'compound', array['anterior_delt','lateral_delt']::text[], array['tricep']::text[], array['shoulders','push','upper_body']::text[], null, 'reps', null, null, 'The upright bench back-support removes leg drive and lower-back sway, isolating the delts and letting a lifter press heavier dumbbells with strict form. The stricter, higher-load seated counterpart to the standing DB press.', array['Sit tall against an upright bench, dumbbells at shoulder height','Press to full extension without shrugging or arching off the pad','Keep the wrists stacked over the elbows','Lower under control to a 90° elbow — do not bounce out of the bottom']::text[], 'dumbbell'),
('smith-machine-shoulder-press', 'Smith Machine Shoulder Press', 'full_gym', 'compound', array['anterior_delt','lateral_delt']::text[], array['tricep']::text[], array['shoulders','push','upper_body']::text[], null, 'reps', null, null, 'The fixed bar path lets a lifter overload overhead pressing safely without a spotter and without the balance demand of free weights — useful for driving delt volume near failure once the stabilisers are fatigued.', array['Set the bench so the bar starts at chin/collarbone height','Back supported and braced; press straight up the fixed track','Lock out overhead without shrugging into the traps','Lower under control to the start; use the safety hooks between sets']::text[], 'machine'),
('cable-rear-delt-fly', 'Cable Rear Delt Fly', 'full_gym', 'isolation', array['posterior_delt']::text[], array['rhomboid']::text[], array['shoulders','back','pull','upper_body']::text[], null, 'reps', null, null, 'Crossing the cables in front and flying them apart keeps constant tension on the rear delt through the full horizontal-abduction arc — including the stretched start where dumbbells have almost none. The cable answer for rear-delt volume and posture balance.', array['Set both pulleys at shoulder height, grab the opposite-side handles (cables crossed)','Fly the arms apart and back in a wide arc, leading with the elbows','Squeeze the rear delts and shoulder blades at the peak','Control the return; keep a soft, fixed elbow bend throughout']::text[], 'cable'),
('lat-pulldown', 'Lat Pulldown', 'full_gym', 'compound', array['lat_dorsi']::text[], array['bicep','posterior_delt','rhomboid']::text[], array['back','pull','upper_body']::text[], null, 'reps', null, 'CAwf7n6Luuc', 'Machine-guided path allows maximum lat loading with a low technique barrier. The primary vertical pull for users who cannot yet do pull-ups — trains the same lat, teres major, and bicep pattern at any strength level.', array['Wide grip, slight backward lean — not upright','Lead with the elbows pulling to back pockets','Squeeze lats at the bottom — not the arms','Full stretch at top: let scapula elevate slightly']::text[], 'machine'),
('pull-up', 'Pull-Up', 'hotel_gym', 'compound', array['lat_dorsi']::text[], array['bicep','posterior_delt','rhomboid','core']::text[], array['back','pull','upper_body']::text[], null, 'reps', null, null, 'Full-body tension, scapular control, grip strength, and core anti-extension all activate simultaneously. Once achievable for multiple clean reps, pull-ups should replace or complement lat pulldown.', array['Dead hang starting position — no kip','Depress and retract scapula BEFORE pulling','Drive elbows toward back pockets','Chin over bar — not just nose over bar']::text[], 'bodyweight'),
('chin-up', 'Chin-Up', 'hotel_gym', 'compound', array['lat_dorsi','bicep_brachii']::text[], array['posterior_delt','rhomboid']::text[], array['back','biceps','pull','upper_body']::text[], null, 'reps', null, null, 'Supinated grip shifts load heavily toward biceps versus pull-ups. Most people can chin-up before they can pull-up — a useful progression. Bicep involvement makes it a two-muscle-in-one movement for smaller day counts.', array['Supinated grip (palms toward face)','Full dead hang at bottom','Elbows drive down and in toward hips','Chin clears bar — pause at top']::text[], 'bodyweight'),
('table-inverted-row', 'Table Inverted Row', 'home', 'compound', array['lat_dorsi']::text[], array['bicep','posterior_delt','rhomboid']::text[], array['back','pull','upper_body']::text[], null, 'reps', null, null, 'The only true zero-equipment pulling compound — a sturdy table (or two chairs and a broomstick) substitutes for a bar. Trains the same horizontal pull pattern as a barbell or dumbbell row with no gym access required.', array['Lie under a sturdy table, hands gripping the edge, body straight','Pull chest toward the table edge, squeezing shoulder blades together','Keep the body rigid — no hip sag','Lower under control; walk feet further out to increase difficulty']::text[], 'bodyweight'),
('straight-arm-pulldown', 'Straight-Arm Pulldown', 'full_gym', 'isolation', array['lat_dorsi']::text[], array['long_head_tricep','posterior_delt']::text[], array['back','pull','upper_body']::text[], null, 'reps', null, null, 'The only movement that isolates the lat without any bicep contribution — the arm stays straight throughout. Trains the lat-to-hip-drive pattern that makes deadlifts and rows stronger.', array['Cable overhead, arms straight throughout','Hinge forward at hips 45°','Drive arms down and back to hips — not to thighs','Squeeze lats at the bottom; arms stop at hip height']::text[], 'cable'),
('band-straight-arm-pulldown', 'Band Straight-Arm Pulldown', 'home', 'isolation', array['lat_dorsi']::text[], array['long_head_tricep','posterior_delt']::text[], array['back','pull','upper_body']::text[], null, 'reps', null, null, 'The only home-tier movement that isolates the lat without any bicep contribution — the arm stays straight throughout, same pattern as the cable version. Trains the lat-to-hip-drive pattern that makes deadlifts and rows stronger, needing only a band anchored overhead.', array['Anchor the band overhead (door anchor or high point), arms straight throughout','Hinge forward at hips 45°','Drive arms down and back to hips — not to thighs','Squeeze lats at the bottom; arms stop at hip height']::text[], 'band'),
('neutral-grip-lat-pulldown', 'Neutral-Grip Lat Pulldown', 'full_gym', 'compound', array['lat_dorsi']::text[], array['bicep','rhomboid','posterior_delt']::text[], array['back','pull','upper_body']::text[], null, 'reps', null, null, 'The neutral (palms-facing) grip keeps the shoulder in its strongest, most impingement-free position and biases the lower lat fibres, allowing a longer pull to the sternum. A shoulder-friendly vertical pull for lifters who feel the wide-grip pulldown in the front of the shoulder.', array['Neutral parallel handle, slight backward lean','Drive the elbows down and in toward the hip pockets','Pull the handle to the upper chest; squeeze the lats at the bottom','Let the scapula rise under control at the top for a full stretch']::text[], 'machine'),
('assisted-pull-up', 'Assisted Pull-Up', 'full_gym', 'compound', array['lat_dorsi']::text[], array['bicep','rhomboid','posterior_delt']::text[], array['back','pull','upper_body']::text[], null, 'reps', null, null, 'Counterweight assistance lets a lifter train the exact pull-up movement pattern before they can do bodyweight reps — building the scapular control and lat strength that bands or lat pulldowns only approximate. The bridge from pulldown to a true pull-up.', array['Kneel or stand on the assist pad; set enough help for 8–10 clean reps','Start from a full dead hang; depress and retract the scapula first','Drive the elbows down and pull the chest toward the bar','Lower under control to a full hang — reduce the assistance as you get stronger']::text[], 'machine'),
('seated-cable-row', 'Seated Cable Row', 'full_gym', 'compound', array['lat_dorsi','rhomboid']::text[], array['bicep','posterior_delt','lower_trap']::text[], array['back','pull','upper_body']::text[], null, 'reps', null, 'UCXxvVItLoM', 'Constant cable tension across the full horizontal range. The bilateral seated position allows heavy loading; hip-to-shoulder bracing mirrors deadlift mechanics.', array['Sit tall, slight forward lean only at stretch','Drive elbows back to hips — not flared out','Squeeze rhomboids at full retraction','Let scapula protract at the stretch — do not shrug']::text[], 'cable'),
('dumbbell-row', 'Dumbbell Row', 'hotel_gym', 'compound', array['lat_dorsi','rhomboid']::text[], array['bicep','posterior_delt']::text[], array['back','pull','upper_body']::text[], null, 'reps', null, 'pYcpY20QaE8', 'Unilateral loading reveals side-to-side strength asymmetries. The braced knee-on-bench position stabilises the spine, making this the safest heavy horizontal pull for newer lifters.', array['Plant knee and same-side hand on bench','Back flat — do not rotate the torso to row','Drive elbow straight back, not out to the side','Touch the weight to the ribcage at the top']::text[], 'dumbbell'),
('barbell-row', 'Barbell Row', 'full_gym', 'compound', array['lat_dorsi','rhomboid','lower_trap']::text[], array['bicep','posterior_delt','erector_spinae']::text[], array['back','pull','upper_body']::text[], null, 'reps', null, null, 'The most demanding horizontal pull — requires total posterior chain engagement to hold the hip hinge under load. No other back exercise builds erector, rhomboid, and mid-trap thickness simultaneously.', array['Hip hinge to 45° — not bent over 90°','Bar stays over mid-foot','Drive elbows to the ceiling, not behind you','Lower under control — the eccentric builds as much mass as the pull']::text[], 'barbell'),
('single-arm-db-row', 'Single-Arm DB Row', 'hotel_gym', 'compound', array['lat_dorsi','rhomboid']::text[], array['bicep','posterior_delt']::text[], array['back','pull','upper_body']::text[], null, 'reps', null, 'pYcpY20QaE8', 'Removes bilateral deficit and forces true unilateral contraction. Greater range of motion than barbell row and safe for any lower back sensitivity.', array['Support non-working side on bench or box','Drive elbow back and up','Keep spine neutral — do not twist','Full extension at bottom for maximum lat stretch']::text[], 'dumbbell'),
('t-bar-row', 'T-Bar Row', 'full_gym', 'compound', array['lat_dorsi','rhomboid','lower_trap']::text[], array['bicep','posterior_delt']::text[], array['back','pull','upper_body']::text[], null, 'reps', null, null, 'Allows the heaviest horizontal pull loading of any machine variation. Neutral grip reduces bicep involvement, keeping more load on the lat and rhomboids.', array['Hinge at hip to 45° over the bar','Neutral grip handles, pull to lower chest','Squeeze hard at peak — hold one count','Lower until full arm extension; let lats stretch']::text[], 'machine'),
('reverse-fly', 'Reverse Fly', 'hotel_gym', 'isolation', array['posterior_delt','rhomboid']::text[], array[]::text[], array['shoulders','back','pull','upper_body']::text[], null, 'reps', null, null, 'Posterior delt isolation without cable required. Critical for scapular retraction strength and shoulder health. Best performed at high reps with light weight.', array['Hinge forward until torso nearly parallel to floor','Start with arms hanging straight down','Lift in a wide arc to shoulder height','Do not swing — reduce weight if you are']::text[], 'dumbbell'),
('band-pull-apart', 'Band Pull-Apart', 'home', 'isolation', array['posterior_delt','rhomboid','external_rotator']::text[], array[]::text[], array['shoulders','back','pull','upper_body']::text[], null, 'reps', null, null, 'The simplest tool for external rotation and posterior delt health. Constant band tension mirrors the load profile of cable face pulls without any machine.', array['Hold band at shoulder height, arms extended','Pull the band apart until it touches your chest','Squeeze shoulder blades together at peak','Controlled return — band tension all the way back to start']::text[], 'band'),
('chest-supported-row', 'Chest-Supported Row', 'full_gym', 'compound', array['lat_dorsi','rhomboid']::text[], array['posterior_delt','lower_trap']::text[], array['back','pull','upper_body']::text[], null, 'reps', null, null, 'The chest pad removes the lower-back and hip-hinge demand entirely, so every bit of effort goes into the mid-back with zero cheating or spinal fatigue. The safest way to row heavy for lifters with any lower-back sensitivity, and the cleanest rhomboid/mid-trap stimulus.', array['Chest firmly on the pad, feet planted','Drive the elbows back, leading with the elbows not the hands','Squeeze the shoulder blades together hard at the top','Let the arms extend fully and the scapula protract at the stretch']::text[], 'machine'),
('pendlay-row', 'Pendlay Row', 'full_gym', 'compound', array['lat_dorsi','rhomboid','lower_trap']::text[], array['bicep','posterior_delt','erector_spinae']::text[], array['back','pull','upper_body']::text[], null, 'reps', null, null, 'Each rep starts dead-stopped from the floor with a flat, parallel torso — eliminating the stretch reflex and momentum so the mid-back must generate the pull explosively from a full stop. Builds rowing power and back thickness a touch-and-go barbell row cannot.', array['Hinge to a torso parallel with the floor, back flat','Bar starts on the floor each rep — reset the position every time','Pull explosively to the lower chest, elbows driving up','Lower under control back to the floor; do not bounce or round the back']::text[], 'barbell'),
('chest-supported-db-row', 'Chest-Supported DB Row', 'hotel_gym', 'compound', array['lat_dorsi','rhomboid']::text[], array['posterior_delt','lower_trap']::text[], array['back','pull','upper_body']::text[], null, 'reps', null, null, 'Lying face-down on an incline bench braces the torso so the mid-back works without any lower-back or hinge involvement — the dumbbell version of the chest-supported row, needing only a bench and dumbbells. Each arm works independently through a full range.', array['Set an incline bench to ~30°, chest on the pad, dumbbells hanging','Row both dumbbells by driving the elbows up and back','Squeeze the shoulder blades together at the top','Lower to a full stretch; keep the chest glued to the pad throughout']::text[], 'dumbbell'),
('db-pullover', 'DB Pullover', 'hotel_gym', 'isolation', array['lat_dorsi']::text[], array['pec_major_sternal','long_head_tricep']::text[], array['back','pull','upper_body']::text[], null, 'reps', null, null, 'The overhead arc loads the lats in a deep stretched position that no row or pulldown reaches, while also hitting the sternal pec and serratus — a classic rib-cage expander and lat-stretch builder needing only one dumbbell and a bench.', array['Lie across or along a bench, both hands cupping one dumbbell','Lower the weight back over the head with soft, fixed elbows','Feel a deep stretch across the lats and ribs at the bottom','Pull it back over the chest by driving with the lats — not the arms']::text[], 'dumbbell'),
('kroc-row', 'Kroc Row', 'hotel_gym', 'compound', array['lat_dorsi','rhomboid']::text[], array['bicep','posterior_delt','upper_trap']::text[], array['back','pull','upper_body']::text[], null, 'reps', null, null, 'A heavy, high-rep single-arm dumbbell row that intentionally allows a little body English to move maximal load for 15–20 reps — building back thickness, grip, and work capacity to failure. The go-to burnout row when the goal is maximum back stimulus and grip overload.', array['Brace a hand/knee on a bench; use a heavy dumbbell','Row explosively to the hip, allowing a slight controlled torso rotation','Drive the elbow high and back; full stretch at the bottom','Use straps if grip fails first; keep the lower back braced, never rounded under the load']::text[], 'dumbbell'),
('machine-high-row', 'Machine High Row', 'full_gym', 'compound', array['lat_dorsi']::text[], array['rhomboid','bicep','posterior_delt']::text[], array['back','pull','upper_body']::text[], null, 'reps', null, null, 'The downward-angled, chest-supported pull biases the upper lats and teres while the pad removes all lower-back and hinge demand — letting a lifter row heavy with a fixed path and independent handles that correct side-to-side imbalances.', array['Chest on the pad, grip the handles overhead-and-out','Pull down and back, driving the elbows toward the hips','Squeeze the lats and shoulder blades at the bottom','Let the arms extend fully at the top for a complete stretch']::text[], 'machine'),
('barbell-curl', 'Barbell Curl', 'full_gym', 'isolation', array['bicep_brachii']::text[], array['brachialis','brachioradialis']::text[], array['biceps','pull','upper_body']::text[], null, 'reps', null, null, 'Supinated grip and bilateral load allow maximum bicep loading. Barbell curl consistently produces the highest peak bicep EMG among curl variations. Bilateral constraint removes any unilateral cheating.', array['Elbows pinned to sides — do not let them drift forward','Supinated grip throughout — do not pronate at top','Full extension at bottom (stretch)','Do not swing — hinge at the elbow only']::text[], 'barbell'),
('db-curl', 'DB Curl', 'hotel_gym', 'isolation', array['bicep_brachii']::text[], array['brachialis','brachioradialis']::text[], array['biceps','pull','upper_body']::text[], null, 'reps', null, null, 'Unilateral loading corrects arm asymmetries. Supination-through-ROM component provides greater short head activation at peak contraction versus barbell. Alternating arms allows slightly higher volume per session.', array['Supinate aggressively at peak — pinky rotates up and inward','Elbows fixed to sides','Full extension at bottom — do not cut the range','Alternate or curl both; control the eccentric']::text[], 'dumbbell'),
('incline-db-curl', 'Incline DB Curl', 'hotel_gym', 'isolation', array['bicep_brachii_long_head']::text[], array['brachialis']::text[], array['biceps','upper_body']::text[], null, 'reps', null, 'soxrZlIl35U', 'The incline position places the long head of the bicep in a stretched starting position — producing greater hypertrophy stimulus than standing curls. Stretch-position loading is one of the most potent hypertrophy signals.', array['Set bench to 60°, lie back with arms hanging free','Curl without moving shoulders forward','Full stretch at the bottom — let gravity pull the arm straight','Squeeze at peak; lower slowly']::text[], 'dumbbell'),
('hammer-curl', 'Hammer Curl', 'hotel_gym', 'isolation', array['brachialis','brachioradialis']::text[], array['bicep_brachii']::text[], array['biceps','upper_body']::text[], null, 'reps', null, 'TwD-YGVP4Bk', 'Neutral grip shifts the primary load to brachialis — the muscle beneath the bicep that pushes it up. A thick brachialis makes the bicep appear larger from every angle. Also trains brachioradialis for forearm size.', array['Neutral grip (thumbs up), do not supinate','Elbows fixed to sides','Can be done simultaneously or alternating','Keep the wrist neutral throughout']::text[], 'dumbbell'),
('cable-curl', 'Cable Curl', 'full_gym', 'isolation', array['bicep_brachii']::text[], array['brachialis']::text[], array['biceps','upper_body']::text[], null, 'reps', null, null, 'Cable provides constant tension at both stretch AND peak positions — dumbbells go easy at the bottom, barbells at the top. Best used as the last bicep exercise when the muscle is pre-fatigued.', array['EZ bar or rope at ankle height','Elbows fixed; do not swing','Full extension at bottom, full contraction at top','Slow the eccentric — that is where growth happens']::text[], 'cable'),
('bayesian-cable-curl', 'Bayesian Cable Curl', 'full_gym', 'isolation', array['bicep_brachii_long_head']::text[], array['brachialis']::text[], array['biceps','upper_body']::text[], null, 'reps', null, null, 'Cable set behind the body keeps the long head under tension through a fully stretched position — unique advantage over all other cable curls. High peak mechanical tension at stretch + constant load = maximum hypertrophy signal.', array['Cable at ankle height behind you','Step forward until arm is stretched behind hip','Curl forward; elbow stays anchored at the hip','Squeeze at full contraction — do not release tension']::text[], 'cable'),
('concentration-curl', 'Concentration Curl', 'hotel_gym', 'isolation', array['bicep_brachii']::text[], array[]::text[], array['biceps','upper_body']::text[], null, 'reps', null, null, 'Braced elbow against inner thigh eliminates any cheating. EMG studies find concentration curl produces peak bicep activation among all dumbbell curls — fully braced position prevents any momentum or shoulder involvement.', array['Sit; elbow braced against inner thigh above the knee','Full extension at bottom — do not rest weight on floor','Supinate aggressively at the top','Squeeze and hold one count at peak']::text[], 'dumbbell'),
('preacher-curl', 'Preacher Curl', 'full_gym', 'isolation', array['bicep_brachii_short_head']::text[], array['brachialis']::text[], array['biceps','upper_body']::text[], null, 'reps', null, null, 'The preacher bench keeps the upper arm anchored forward — preventing shoulder involvement and maximising short head activation at the bottom stretch position. The most isolated bicep exercise in any gym.', array['Upper arm flat against pad throughout','Full extension at the bottom — allow the full stretch','Curl up; do not yank — controlled throughout','Lower slowly and with resistance — the eccentric is crucial']::text[], 'machine'),
('ez-bar-curl', 'EZ-Bar Curl', 'full_gym', 'isolation', array['bicep_brachii']::text[], array['brachialis','brachioradialis']::text[], array['biceps','pull','upper_body']::text[], null, 'reps', null, null, 'The angled EZ bar puts the wrists in a semi-supinated position that loads the biceps nearly as hard as a straight bar while sparing the wrist and elbow joints — letting most lifters curl heavy pain-free. The default heavy bilateral curl for anyone the straight bar bothers.', array['Grip the inner angles of the bar, elbows pinned to the sides','Curl without letting the elbows drift forward','Full contraction at the top, full extension at the bottom','Lower under control — no swinging or hip drive']::text[], 'barbell'),
('spider-curl', 'Spider Curl', 'hotel_gym', 'isolation', array['bicep_brachii_short_head']::text[], array['brachialis']::text[], array['biceps','upper_body']::text[], null, 'reps', null, null, 'Curling with the arms hanging straight down off the front of an incline bench removes all momentum and keeps the biceps under peak tension in the shortened position — biasing the short head. The strictest curl for peak contraction without cheating.', array['Lie face-down on an incline bench, arms hanging straight down','Curl the dumbbells up without moving the upper arms','Squeeze hard at the top — the arms are vertical, tension is peak','Lower slowly to a full stretch; do not swing']::text[], 'dumbbell'),
('reverse-curl', 'Reverse Curl', 'full_gym', 'isolation', array['brachioradialis','brachialis']::text[], array['bicep_brachii']::text[], array['biceps','upper_body']::text[], null, 'reps', null, null, 'The pronated (palms-down) grip shifts load onto the brachioradialis and brachialis — the forearm and underlying arm muscles that add width and thickness the supinated curl misses. Essential for complete, balanced arm and forearm development.', array['Pronated grip (palms down), shoulder-width, elbows at the sides','Curl up keeping the wrists neutral — do not let them drop','Squeeze at the top; the forearms should work hard','Lower slowly and under full control']::text[], 'barbell'),
('zottman-curl', 'Zottman Curl', 'hotel_gym', 'isolation', array['bicep_brachii']::text[], array['brachioradialis','brachialis']::text[], array['biceps','upper_body']::text[], null, 'reps', null, null, 'Curling up supinated then rotating to pronated for the lowering phase trains the biceps concentrically and the forearm extensors/brachioradialis eccentrically in one rep — the most efficient single movement for building the biceps and forearms together.', array['Curl up with palms facing up (supinated)','At the top, rotate the wrists to palms-down (pronated)','Lower slowly in the pronated position — resist hard','Rotate back to supinated at the bottom for the next rep']::text[], 'dumbbell'),
('cross-body-hammer-curl', 'Cross-Body Hammer Curl', 'hotel_gym', 'isolation', array['brachialis','brachioradialis']::text[], array['bicep_brachii']::text[], array['biceps','upper_body']::text[], null, 'reps', null, null, 'Curling the dumbbell across the body toward the opposite shoulder maximises brachialis and brachioradialis recruitment through a line of pull that emphasises the peak — building the arm thickness and width that supinated curls miss.', array['Neutral grip; curl one dumbbell across toward the opposite pec','Keep the elbow pinned at the side — do not let it swing forward','Squeeze at the top near the opposite shoulder','Lower under control; alternate arms each rep']::text[], 'dumbbell'),
('cable-rope-hammer-curl', 'Cable Rope Hammer Curl', 'full_gym', 'isolation', array['brachialis','brachioradialis']::text[], array['bicep_brachii']::text[], array['biceps','upper_body']::text[], null, 'reps', null, null, 'The rope keeps a neutral grip under constant cable tension through the whole range — including the stretch at the bottom where dumbbells go slack — making it the most consistent brachialis/brachioradialis builder for arm thickness.', array['Rope attachment at the low pulley, neutral grip','Curl up keeping the elbows pinned to the sides','Flare the rope ends apart slightly at the top for peak squeeze','Lower slowly against the constant cable tension']::text[], 'cable'),
('band-curl', 'Band Curl', 'home', 'isolation', array['bicep_brachii']::text[], array['brachialis','brachioradialis']::text[], array['biceps','pull','upper_body']::text[], null, 'reps', null, null, 'The standard supinated curl pattern, needing only a band anchored underfoot — band tension rises through the range, peaking near the top where the bicep is already strongest, unlike a dumbbell which goes light at lockout.', array['Stand on the band, one handle in each hand, supinated grip','Elbows pinned to sides — do not let them drift forward','Full extension at bottom (stretch)','Squeeze at the top; do not swing — hinge at the elbow only']::text[], 'band'),
('band-hammer-curl', 'Band Hammer Curl', 'home', 'isolation', array['brachialis','brachioradialis']::text[], array['bicep_brachii']::text[], array['biceps','upper_body']::text[], null, 'reps', null, null, 'Neutral grip shifts the primary load to brachialis — the muscle beneath the bicep that pushes it up — same as the dumbbell version, using only a band anchored underfoot. Also trains brachioradialis for forearm size.', array['Stand on the band, neutral grip (thumbs up), one handle in each hand','Elbows fixed to sides','Can be done simultaneously or alternating','Keep the wrist neutral throughout']::text[], 'band'),
('tricep-rope-pushdown', 'Tricep Rope Pushdown', 'full_gym', 'isolation', array['tricep_lateral','tricep_medial']::text[], array[]::text[], array['triceps','push','upper_body']::text[], null, 'reps', null, '2-LAMcpzODU', 'Lateral and medial tricep head isolation. The rope allows wrists to flare outward at lockout, adding a final squeeze that straight-bar pushdowns prevent. These two heads are most visible from behind and make the arm look bigger in shirts.', array['Elbows pinned to sides — forearms are the only moving part','Flare the rope ends outward at lockout for peak contraction','Control the return — do not let the rope pull elbows forward','Slight forward lean is fine; do not bend at the hips']::text[], 'cable'),
('tricep-overhead-extension', 'Tricep Overhead Extension', 'hotel_gym', 'isolation', array['tricep_long_head']::text[], array[]::text[], array['triceps','upper_body']::text[], null, 'reps', null, 'nRiJVZDpdL0', 'The long head of the tricep is 55% of total tricep mass and is ONLY fully activated in overhead position. Most programs do only pushdowns, leaving the biggest head undertrained. Without overhead extension, half your tricep potential is untapped.', array['Hold one dumbbell with both hands overhead (diamond grip)','Elbows point to the ceiling — do not flare','Lower behind the head until forearms are parallel','Press back up through the elbows — do not swing']::text[], 'dumbbell'),
('skull-crusher', 'Skull Crusher', 'full_gym', 'isolation', array['tricep_long_head','tricep_medial']::text[], array[]::text[], array['triceps','upper_body']::text[], null, 'reps', null, null, 'The lying EZ-bar variation loads the long head in a lengthened position (elbow overhead relative to torso) while allowing heavier loads than dumbbell overhead extensions. Gold standard for tricep mass work.', array['Lie on bench, bar above lower chest to start','Lower to forehead or behind head by bending elbows only','Keep upper arms vertical — elbows do not drift toward feet','Press back up; do not let the bar drift into a press']::text[], 'barbell'),
('cable-overhead-extension', 'Cable Overhead Extension', 'full_gym', 'isolation', array['tricep_long_head']::text[], array[]::text[], array['triceps','upper_body']::text[], null, 'reps', null, null, 'Constant cable tension through the full overhead range — the peak stretch position has full load, unlike dumbbells. Best performed facing away from the cable stack.', array['Face away from cable, rope at head height','Lean forward slightly; elbows beside the head','Extend to full lockout overhead','Lower slowly until maximum stretch — do not rush the negative']::text[], 'cable'),
('db-kickback', 'DB Kickback', 'hotel_gym', 'isolation', array['tricep_lateral','tricep_medial']::text[], array[]::text[], array['triceps','upper_body']::text[], null, 'reps', null, null, 'Fully extends the elbow against gravity at a position where the tricep is maximally shortened. Better than cable for lateral head contraction quality.', array['Hinge forward, upper arm parallel to floor throughout','Only the forearm moves — hinge at the elbow','Extend until arm is fully straight — hold one count','Lower slowly; resist the temptation to swing']::text[], 'dumbbell'),
('straight-bar-pushdown', 'Straight-Bar Pushdown', 'full_gym', 'isolation', array['tricep_lateral','tricep_medial']::text[], array[]::text[], array['triceps','push','upper_body']::text[], null, 'reps', null, null, 'The fixed straight bar keeps the forearms pronated and lets a lifter push heavier than the rope, driving the lateral and medial heads with more absolute load. The heavy-loading complement to the rope pushdown for tricep thickness.', array['Straight or slightly-bent bar at upper-chest height','Elbows pinned to the sides — only the forearms move','Extend to a full lockout and squeeze the triceps','Control the return; do not let the elbows drift up']::text[], 'cable'),
('bench-dip', 'Bench Dip', 'home', 'isolation', array['tricep_lateral','tricep_medial']::text[], array['anterior_delt']::text[], array['triceps','push','upper_body']::text[], null, 'reps', null, null, 'A bodyweight triceps builder needing only a bench, chair, or step — the vertical descent loads all three heads and progresses easily by elevating the feet or setting a plate on the lap. The go-to triceps overload with no gym access.', array['Hands on the bench edge behind you, legs out front','Lower by bending the elbows straight back — keep them tucked','Descend until the upper arms are parallel to the floor','Press back to a full lockout; keep the hips close to the bench']::text[], 'bodyweight'),
('tricep-dip-machine', 'Tricep Dip Machine', 'full_gym', 'isolation', array['tricep_lateral','tricep_medial','tricep_long_head']::text[], array[]::text[], array['triceps','push','upper_body']::text[], null, 'reps', null, null, 'The seated dip machine loads all three triceps heads through a full pressing range with a fixed, back-supported path — letting a lifter push close to failure safely and progress in small increments. A joint-friendly heavy triceps option late in a session.', array['Sit tall, back against the pad, hands on the handles','Press down to a full elbow lockout — drive through the triceps','Squeeze at the bottom for one count','Return under control to a 90° elbow; do not let the stack slam']::text[], 'machine'),
('diamond-push-up', 'Diamond Push-Up', 'home', 'isolation', array['tricep_lateral','tricep_medial']::text[], array['pec_major_sternal','anterior_delt']::text[], array['triceps','push','upper_body']::text[], null, 'reps', null, null, 'The narrow diamond hand position shifts a standard push-up’s load heavily onto the triceps — producing among the highest triceps EMG of any bodyweight movement. Zero-equipment triceps mass work; elevate the feet to progress.', array['Hands together under the chest, index fingers and thumbs forming a diamond','Body rigid in a straight line — no hip sag','Lower until the chest nearly touches the hands, elbows tucked','Press to full lockout; elevate the feet to add difficulty']::text[], 'bodyweight'),
('jm-press', 'JM Press', 'full_gym', 'isolation', array['tricep_long_head','tricep_medial']::text[], array['anterior_delt']::text[], array['triceps','push','upper_body']::text[], null, 'reps', null, null, 'A hybrid of the close-grip press and the skull crusher — the bar lowers toward the upper neck with the elbows forward, loading the triceps at a long muscle length while still allowing heavy barbell loading. A powerlifting staple for lockout strength and triceps mass.', array['Lie on a bench, close (shoulder-width) grip','Lower the bar toward the upper chest/neck with elbows drifting forward','Stop at the bottom shelf position, then press back up','Keep it strict — heavier than a skull crusher, lighter than a close-grip press']::text[], 'barbell'),
('single-arm-cable-kickback', 'Single-Arm Cable Kickback', 'full_gym', 'isolation', array['tricep_lateral','tricep_medial']::text[], array[]::text[], array['triceps','upper_body']::text[], null, 'reps', null, null, 'The cable holds tension at the fully-shortened lockout where a dumbbell kickback goes weightless — giving a hard peak contraction on the lateral and medial heads, one arm at a time to correct side-to-side deficits.', array['Low pulley, hinge forward, upper arm parallel to the floor and fixed','Extend only the forearm to a full lockout — the elbow does not move','Squeeze hard at full extension against the constant cable tension','Control the return; keep the torso still, do not swing']::text[], 'cable'),
('barbell-back-squat', 'Barbell Back Squat', 'full_gym', 'compound', array['quad_rectus_femoris','quad_vastus_lateralis','quad_vastus_medialis','quad_vastus']::text[], array['glute_max','hamstring','erector_spinae']::text[], array['quads','glutes','lower_body']::text[], null, 'reps', null, null, 'The highest total-muscle-mass exercise in existence — quads, hamstrings, glutes, erectors, core, and upper back all contribute. No other movement builds as much lower body mass in one movement.', array['Bar on upper traps (high bar) or lower traps (low bar)','Feet shoulder-width, toes 15–30° out','Brace hard — breath in and hold through the descent','Knees track over toes; do not cave']::text[], 'barbell'),
('hack-squat', 'Hack Squat', 'full_gym', 'compound', array['quad_vastus_lateralis','quad_vastus_medialis','quad_vastus']::text[], array['glute_max']::text[], array['quads','lower_body']::text[], null, 'reps', null, 'MKcAc4RoKME', 'Machine allows heavier quad loading than most free-weight squats — all force goes into the quad, not balance. The vertical sled path eliminates spinal compression, making this the safest heavy quad compound for those with back issues.', array['Feet shoulder-width on platform, toes slightly out','Keep heels flat — do not rise on toes at the bottom','Descend to 90° or lower if mobility allows','Drive through heels to extend']::text[], 'machine'),
('leg-press', 'Leg Press', 'full_gym', 'compound', array['quad_rectus_femoris','quad_vastus_lateralis','quad_vastus']::text[], array['glute_max','hamstring']::text[], array['quads','lower_body']::text[], null, 'reps', null, 'IZxyjW7MPJQ', 'No spinal loading, no balance — all force into the quads. Useful for quad volume when the lower back is fatigued. High-and-wide foot placement biases glutes/hamstrings; low-and-narrow biases quads.', array['Do not lock out the knees at the top — maintain tension','Lower until thighs are 90° or below','Feet centred on platform for balanced quad loading','Back flat against pad; do not round the lower back at the bottom']::text[], 'machine'),
('leg-extension', 'Leg Extension', 'full_gym', 'isolation', array['quad_rectus_femoris','quad_vastus_medialis','quad_vastus']::text[], array[]::text[], array['quads','lower_body']::text[], null, 'reps', null, 'YyvSfVjQeL0', 'The only isolation exercise for the quadriceps. The rectus femoris (bi-articular quad head) is placed under stretch here that compound movements cannot achieve. Essential for complete quad development.', array['Adjust pad to sit just above ankle — not on the foot','Slow to full extension; do not kick','Hold at the top for one second — peak quad contraction','Lower slowly — the eccentric matters as much as the lift']::text[], 'machine'),
('sissy-squat', 'Sissy Squat', 'home', 'isolation', array['quad_rectus_femoris','quad_vastus_lateralis','quad_vastus_medialis','quad_vastus']::text[], array[]::text[], array['quads','lower_body']::text[], null, 'reps', null, null, 'The bodyweight answer to the leg extension — knees travel far forward while the hips stay extended, isolating the quads (especially the rectus femoris) under a deep stretch with zero equipment. Ideal quad finisher requiring nothing but bodyweight.', array['Hold a support for balance; rise onto the balls of the feet','Drive knees forward and lean the torso back in one line','Lower until you feel a deep quad stretch — hips stay open','Squeeze the quads to return; add a plate hugged to the chest to progress']::text[], 'bodyweight'),
('reverse-nordic', 'Reverse Nordic', 'home', 'isolation', array['quad_rectus_femoris','quad_vastus_lateralis','quad_vastus_medialis','quad_vastus']::text[], array[]::text[], array['quads','lower_body']::text[], null, 'reps', null, null, 'A kneeling eccentric quad isolation that loads the rectus femoris under a long stretch — the exact lengthened-position stimulus the leg extension cannot reach. Builds quads and knee resilience with zero equipment.', array['Kneel tall, hips fully extended, core braced','Lean the whole body back in a straight line from knees to head','Lower as far as quad control allows — no hip bend','Pull back up with the quads; hold a wall or band to assist if needed']::text[], 'bodyweight'),
('bodyweight-squat', 'Bodyweight Squat', 'home', 'compound', array['quad_rectus_femoris','quad_vastus_medialis','quad_vastus']::text[], array['glute_max']::text[], array['quads','lower_body']::text[], null, 'reps', null, null, 'The zero-equipment squat pattern — full knee and hip flexion trains the quads through a complete range of motion. The foundational lower-body compound when no external load is available; add tempo, pauses, or a loaded backpack to progress.', array['Feet shoulder-width, toes slightly out','Sit hips back and down — knees track over toes','Drive through the whole foot to stand','Chest tall throughout — brace the core before descending']::text[], 'bodyweight'),
('goblet-squat', 'Goblet Squat', 'hotel_gym', 'compound', array['quad_rectus_femoris','quad_vastus_medialis','quad_vastus']::text[], array['glute_max','core']::text[], array['quads','lower_body']::text[], null, 'reps', null, 'MeIiIdhvXT4', 'The counterbalance weight allows an upright torso and deep knee bend that many lifters cannot achieve in a barbell squat. Best learning tool for squat mechanics and an excellent quad compound in any setting.', array['Hold DB or KB at chest height — elbows between knees at bottom','Push knees out over toes','Chest tall throughout — do not collapse forward','Drive up through the heels']::text[], 'dumbbell'),
('bulgarian-split-squat', 'Bulgarian Split Squat', 'hotel_gym', 'compound', array['quad_rectus_femoris','quad_vastus_lateralis','quad_vastus']::text[], array['glute_max','hamstring']::text[], array['quads','glutes','lower_body']::text[], null, 'reps', null, '2C-uNgKwPLE', 'Rear foot elevation increases hip flexor stretch and hip flexion depth — a training stimulus unavailable in bilateral squatting. Highest correlation to athletic performance (sprint speed, jump height) among all unilateral leg movements.', array['Front foot far enough forward that shin stays vertical','Lower straight down — do not lean forward','Drive through the heel of the front foot','Rear leg is a kickstand only — it should not push']::text[], 'dumbbell'),
('db-lunge', 'DB Lunge', 'hotel_gym', 'compound', array['quad_rectus_femoris','quad_vastus']::text[], array['glute_max','hamstring','core']::text[], array['quads','glutes','lower_body']::text[], null, 'reps', null, null, 'Walking lunges produce the highest glute activation of any lunge variation due to the hip extension into the step. The bilateral instability challenge builds proprioception and ankle stability more than any stationary squat.', array['Step forward; lower until back knee is one inch from floor','Keep torso upright — do not lean forward','Drive through front heel to step through','Keep dumbbells at sides — do not let them swing']::text[], 'dumbbell'),
('step-up', 'Step-Up', 'hotel_gym', 'compound', array['quad_rectus_femoris','glute_max','quad_vastus']::text[], array['hamstring']::text[], array['quads','glutes','lower_body']::text[], null, 'reps', null, null, 'The most sport-specific lower body exercise — replicates stair climbing, hill sprinting, and any real-world stepping movement. Single-leg loading makes it useful for diagnosing bilateral deficits.', array['Box height: upper thigh parallel at 90° when foot is on box','Drive through the heel of the elevated foot','Do not push off the back foot — it should barely touch','Lower slowly — the step down is just as important as the step up']::text[], 'dumbbell'),
('front-squat', 'Front Squat', 'full_gym', 'compound', array['quad_rectus_femoris','quad_vastus_lateralis','quad_vastus_medialis','quad_vastus']::text[], array['glute_max','erector_spinae','upper_trap']::text[], array['quads','lower_body']::text[], null, 'reps', null, null, 'The front-rack position forces an upright torso, shifting load off the hips and directly onto the quads while demanding heavy upper-back and core bracing to stay tall. The most quad-dominant barbell squat, and easier on the lower back than a back squat.', array['Bar in the front rack: elbows high, resting on the front delts','Brace hard; descend straight down, knees tracking over the toes','Keep the torso as vertical as possible — elbows up throughout','Drive through the whole foot to stand; do not let the chest drop']::text[], 'barbell'),
('db-split-squat', 'DB Split Squat', 'hotel_gym', 'compound', array['quad_rectus_femoris','quad_vastus_lateralis','quad_vastus']::text[], array['glute_max']::text[], array['quads','lower_body']::text[], null, 'reps', null, null, 'A stationary split stance (both feet on the floor) delivers most of the unilateral quad stimulus of a Bulgarian split squat with far less balance demand — an accessible single-leg builder for lifters not yet ready to elevate the rear foot.', array['Split stance, front shin vertical, torso upright','Lower straight down until the back knee nearly touches the floor','Drive through the front heel to stand','Keep the dumbbells hanging at the sides; complete all reps, then switch']::text[], 'dumbbell'),
('reverse-lunge', 'Reverse Lunge', 'hotel_gym', 'compound', array['quad_rectus_femoris','quad_vastus']::text[], array['glute_max','hamstring']::text[], array['quads','glutes','lower_body']::text[], null, 'reps', null, null, 'Stepping backward keeps the front shin more vertical and the weight over the front heel — far easier on the knee than a forward lunge while still loading the quad and glute hard. The knee-friendly single-leg builder and a better fit for lifters with knee sensitivity.', array['Step one foot straight back, lowering the back knee toward the floor','Keep the front shin near vertical, torso tall','Drive through the front heel to return to standing','Dumbbells at the sides; complete all reps or alternate legs']::text[], 'dumbbell'),
('smith-machine-squat', 'Smith Machine Squat', 'full_gym', 'compound', array['quad_rectus_femoris','quad_vastus_lateralis','quad_vastus_medialis','quad_vastus']::text[], array['glute_max']::text[], array['quads','lower_body']::text[], null, 'reps', null, null, 'The fixed bar path lets a lifter place the feet slightly forward and sit straight down, biasing the quads with less balance and lower-back demand than a free squat — a safe way to overload the legs close to failure without a spotter.', array['Feet slightly forward of the bar, shoulder-width','Descend straight down to at least parallel, knees tracking the toes','Keep the whole foot planted; drive up through the mid-foot','Use the safety hooks to rack; do not lock out harshly at the top']::text[], 'machine'),
('landmine-squat', 'Landmine Squat', 'full_gym', 'compound', array['quad_rectus_femoris','quad_vastus_medialis','quad_vastus']::text[], array['glute_max','core']::text[], array['quads','lower_body']::text[], null, 'reps', null, null, 'The landmine arc supports the load in front and lets a lifter stay upright through a deep squat — the most back-friendly loaded squat pattern, ideal for those who cannot comfortably back- or front-squat but still want heavy quad work.', array['Hold the barbell end at the chest, feet shoulder-width','Sit straight down, letting the arc guide the bar','Keep the chest tall and the torso upright throughout','Drive through the heels to stand; the bar path is an arc, not vertical']::text[], 'barbell'),
('romanian-deadlift', 'Romanian Deadlift', 'full_gym', 'compound', array['hamstring','glute_max']::text[], array['erector_spinae','adductor']::text[], array['hamstrings','glutes','lower_body']::text[], null, 'reps', null, 'JCXUYuzwNrM', 'Trains the hamstring in its most important function: hip extension under eccentric load. The stretch position at the bottom produces the highest mechanotransduction signal of any hamstring exercise. Fundamental for any strength program.', array['Hip hinge, not a squat — push hips back','Bar stays in contact with legs throughout','Feel the hamstring stretch; stop before lower back rounds','Drive hips forward to return — squeeze glutes at top']::text[], 'barbell'),
('bodyweight-single-leg-rdl', 'Single-Leg Romanian Deadlift', 'home', 'compound', array['hamstring','glute_max']::text[], array['erector_spinae']::text[], array['hamstrings','glutes','lower_body']::text[], null, 'reps', null, null, 'The zero-equipment hip-hinge compound — balancing on one leg increases hamstring and glute demand to compensate for the lack of external load. Trains the same hip-extension pattern as the barbell RDL with no equipment required.', array['Stand tall, soft bend in the standing knee','Hinge forward while the free leg extends straight back','Keep hips square — do not let them rotate open','Squeeze the glute and hamstring to return to standing; hold a wall for balance if needed']::text[], 'bodyweight'),
('lying-leg-curl', 'Lying Leg Curl', 'full_gym', 'isolation', array['hamstring_bicep_femoris']::text[], array[]::text[], array['hamstrings','lower_body']::text[], null, 'reps', null, 'ELOCsoDSmrg', 'Knee flexion trains the short head of bicep femoris — the only head that cannot be reached with any hip hinge movement. Both hamstring functions (knee flexion AND hip extension) must be trained for complete development.', array['Pad just above the heel, not on the Achilles','Curl all the way up to maximum knee flexion','Do not let the hips lift off the pad','Lower slowly — do not let the weight slam']::text[], 'machine'),
('seated-leg-curl', 'Seated Leg Curl', 'full_gym', 'isolation', array['hamstring_bicep_femoris','hamstring_semimembranous']::text[], array[]::text[], array['hamstrings','lower_body']::text[], null, 'reps', null, 'YyvSfVjQeL0', 'The seated position places hamstrings under stretch at both hip AND knee simultaneously — producing greater EMG activity than lying leg curl. A hamstring under hip-flexion tension is longer, increasing the hypertrophy stimulus.', array['Sit tall; thigh pad positioned just above the knee','Curl all the way to maximum knee flexion','Squeeze at peak — hold one count','Slow eccentric — resist the return all the way']::text[], 'machine'),
('nordic-curl', 'Nordic Curl', 'hotel_gym', 'isolation', array['hamstring_biceps_femoris','hamstring_semimembranosus','hamstring_semitendinosus']::text[], array[]::text[], array['hamstrings','lower_body']::text[], null, 'reps', null, null, 'Reduces hamstring strain injury risk by 50–70% per multiple RCTs. The eccentric-only loading at long muscle lengths is unique and irreplaceable. The single highest return-on-investment exercise in sports medicine.', array['Anchor feet under heavy object or have partner hold','Lower as slowly as possible using hamstrings — catch yourself with hands','Goal is to resist as long as possible on the way down','Beginner: use hands to help push up; advanced: pull back up with hamstrings']::text[], 'bodyweight'),
('slider-leg-curl', 'Slider Leg Curl', 'home', 'isolation', array['hamstring_biceps_femoris','hamstring_semimembranosus','hamstring_semitendinosus']::text[], array[]::text[], array['hamstrings','lower_body']::text[], null, 'reps', null, null, 'Replicates the machine leg curl with only a towel or furniture slider. Lying glute-bridge position keeps the hips extended while the knees flex, loading the hamstrings concentrically and eccentrically — a true knee-flexion isolation when no machine exists.', array['Lie supine, heels on sliders/towels, hips lifted to a bridge','Keep hips up throughout — do not let them sag','Extend legs out under control, then curl heels back to the glutes','Both legs together to start; single-leg to progress']::text[], 'bodyweight'),
('good-morning', 'Good Morning', 'full_gym', 'compound', array['hamstring','erector_spinae','glute_max']::text[], array[]::text[], array['hamstrings','lower_body']::text[], null, 'reps', null, null, 'Simultaneously trains hamstring and erector at long muscle lengths under heavy load — rare among exercises. The erector strengthening component is the primary benefit for anyone prone to lower back fatigue in the big lifts.', array['Bar on upper back, feet shoulder-width','Hip hinge: push hips back, not down','Keep knees soft (not locked out)','Rise by driving hips forward — same pattern as RDL']::text[], 'barbell'),
('db-rdl', 'DB RDL', 'hotel_gym', 'compound', array['hamstring','glute_max']::text[], array['erector_spinae']::text[], array['hamstrings','glutes','lower_body']::text[], null, 'reps', null, null, 'Identical hip hinge to barbell RDL but accessible with just a pair of dumbbells. The dumbbell version allows a slightly more natural arc and is easier to set up without a squat rack.', array['Dumbbells hang at thigh level — slide them down the legs','Hip hinge back; feel the hamstring stretch at the bottom','Flat back throughout — brace the core hard','Drive hips forward to return; squeeze glutes at the top']::text[], 'dumbbell'),
('single-leg-db-rdl', 'Single-Leg DB RDL', 'hotel_gym', 'compound', array['hamstring','glute_max']::text[], array['erector_spinae']::text[], array['hamstrings','glutes','lower_body']::text[], null, 'reps', null, null, 'Loading the single-leg hip hinge with a dumbbell doubles the demand on one hamstring and glute while exposing left-right imbalances the barbell RDL hides. The balance challenge also builds ankle and hip stability that carries into every bilateral lift.', array['Dumbbell in the opposite hand to the working leg, soft standing knee','Hinge forward as the free leg extends straight back — hips square','Feel the hamstring stretch; keep the back flat, do not round','Drive the hip forward to stand and squeeze the glute; finish all reps, then switch']::text[], 'dumbbell'),
('stiff-leg-deadlift', 'Stiff-Leg Deadlift', 'full_gym', 'compound', array['hamstring','glute_max']::text[], array['erector_spinae']::text[], array['hamstrings','glutes','lower_body']::text[], null, 'reps', null, null, 'Lifting from the floor with near-locked knees keeps the hamstrings under a long, loaded stretch through the entire range — a heavier, larger-ROM cousin of the RDL that maximises the stretch-mediated hypertrophy signal on the hamstrings and glutes.', array['Bar on the floor, knees soft but nearly straight and fixed','Hinge to grip the bar; keep the back flat, chest up','Drive the hips forward to stand — the bar rides up the legs','Lower with control, pushing the hips back; stop if the back rounds']::text[], 'barbell'),
('glute-ham-raise', 'Glute-Ham Raise', 'full_gym', 'isolation', array['hamstring_biceps_femoris','hamstring_semimembranosus','hamstring_semitendinosus']::text[], array['glute_max','erector_spinae']::text[], array['hamstrings','glutes','lower_body']::text[], null, 'reps', null, null, 'The GHD trains both hamstring functions at once — knee flexion and hip extension — under a bodyweight eccentric that builds hamstring strength and injury resilience second only to the Nordic curl. A premier posterior-chain accessory where a GHD bench is available.', array['Feet anchored on the GHD, thighs on the pad','Lower the torso under control by extending at the knees','At full stretch, curl back up by driving the heels into the platform','Keep the hips extended throughout — do not turn it into a hinge']::text[], 'machine'),
('hip-thrust', 'Hip Thrust', 'hotel_gym', 'compound', array['glute_max']::text[], array[]::text[], array['glutes','lower_body']::text[], null, 'reps', null, 'SEdqd1n0cvg', 'Greatest glute EMG activation of any exercise. The fully shortened position at peak (hip fully extended) is unique — squats and deadlifts never achieve full hip extension under load. Trains the glute in its most powerful position.', array['Upper back on bench, shoulder blades on edge','Drive through heels, not toes','Tuck chin to chest — do not hyperextend the neck','Squeeze glutes aggressively at top; do not hyperextend the lower back']::text[], 'dumbbell'),
('barbell-hip-thrust', 'Barbell Hip Thrust', 'full_gym', 'compound', array['glute_max']::text[], array[]::text[], array['glutes','lower_body']::text[], null, 'reps', null, null, 'Allows load progression far beyond dumbbell — advanced lifters can hip thrust 300+ lbs. For maximum glute development, the barbell is the only viable option once dumbbell loading becomes insufficient.', array['Use a barbell pad or folded mat for hip comfort','Bar sits in the hip crease throughout','Drive through the entire foot, not the heel only','Full lockout: core braced, glutes squeezed, do not arch the lower back']::text[], 'barbell'),
('cable-kickback', 'Cable Kickback', 'full_gym', 'isolation', array['glute_max']::text[], array['hamstring']::text[], array['glutes','lower_body']::text[], null, 'reps', null, null, 'Isolates glute max at the hip extension endpoint, adding peak-squeeze volume that compound movements cannot achieve. Best used as a finishing accessory after heavy hip thrusts and RDLs.', array['Ankle cuff attached; face the cable stack','Slight forward lean, hands on the stack for support','Kick straight back until hip is fully extended — no lateral rotation','Squeeze at peak; lower with resistance']::text[], 'cable'),
('abductor-machine', 'Abductor Machine', 'full_gym', 'isolation', array['glute_medius','glute_minimus']::text[], array[]::text[], array['glutes','lower_body']::text[], null, 'reps', null, 'GKumTNiuCLY', 'Glute medius and minimus are lateral hip stabilisers — their weakness causes knee valgus, IT band syndrome, and hip drop during running. The most targeted way to build these muscles.', array['Sit upright — do not lean back to recruit hip flexors','Drive knees apart from the hip, not the knee','Full range: start with knees together, drive as wide as possible','Slow return — the eccentric builds as much as the drive']::text[], 'machine'),
('sumo-rdl', 'Sumo RDL', 'full_gym', 'compound', array['glute_max','glute_medius','adductor']::text[], array['hamstring']::text[], array['glutes','lower_body']::text[], null, 'reps', null, null, 'Wide stance shifts the hip extension pattern toward glutes and adductors rather than the hamstring-dominant conventional stance. Particularly responsive for lifters whose anatomy favours a wider hip hinge.', array['Feet 2× shoulder-width; toes point 45° outward','Push hips back — same hinge pattern as conventional RDL','Let bar travel in a straight vertical line','Drive knees out over toes as you stand']::text[], 'barbell'),
('glute-bridge', 'Glute Bridge', 'home', 'isolation', array['glute_max']::text[], array[]::text[], array['glutes','lower_body']::text[], null, 'reps', null, null, 'Identical mechanics to hip thrust but performed on the floor. Shorter ROM but identical glute squeeze at the top. The go-to glute exercise when no bench is available. Can be loaded with a plate across the hips.', array['Supine on floor, feet flat and close to hips','Drive through heels; lift hips until body is a plank','Squeeze glutes hard at top — hold two counts','Lower with control; do not drop hips to the floor between reps']::text[], 'bodyweight'),
('single-leg-glute-bridge', 'Single-Leg Glute Bridge', 'home', 'isolation', array['glute_max']::text[], array['hamstring']::text[], array['glutes','lower_body']::text[], null, 'reps', null, null, 'Doubles the load on one glute using only bodyweight, exposing and correcting side-to-side imbalances the two-leg bridge hides. The go-to glute isolation when no bench or weight is available.', array['Supine, one foot flat, the other leg extended','Drive through the planted heel; keep hips level — no tilt','Squeeze the glute hard at the top for two counts','Lower with control; complete all reps, then switch sides']::text[], 'bodyweight'),
('banded-hip-abduction', 'Banded Hip Abduction', 'home', 'isolation', array['glute_medius','glute_minimus']::text[], array[]::text[], array['glutes','lower_body']::text[], null, 'reps', null, null, 'Targets the glute medius and minimus — the lateral hip stabilisers whose weakness drives knee valgus and hip drop. A mini-band replaces the abductor machine with near-identical isolation anywhere.', array['Loop a mini-band just above the knees','Standing or side-lying, drive the knee out against the band','Keep the pelvis still — move only at the hip','Slow return; never let the band snap the leg back']::text[], 'band'),
('cable-pull-through', 'Cable Pull-Through', 'full_gym', 'compound', array['glute_max']::text[], array['hamstring','erector_spinae']::text[], array['glutes','lower_body']::text[], null, 'reps', null, null, 'The cable line of pull loads the hip hinge horizontally, peaking exactly at full hip extension where the glutes contract hardest — teaching the hinge with constant tension and no spinal loading. An ideal glute-focused hinge for high volume without lower-back fatigue.', array['Face away from a low pulley, rope between the legs','Hinge back, letting the rope draw the hands between the thighs','Drive the hips forward to stand; squeeze the glutes at lockout','Do not turn it into a squat or a back extension — the motion is at the hip']::text[], 'cable'),
('curtsy-lunge', 'Curtsy Lunge', 'hotel_gym', 'compound', array['glute_max','glute_medius']::text[], array['quad_rectus_femoris','quad_vastus']::text[], array['glutes','lower_body']::text[], null, 'reps', null, null, 'Stepping the working leg behind and across the body places the glute medius under stretch and load — the frontal-plane hip work that forward and reverse lunges miss. Builds the lateral glute that shapes the hip and stabilises the knee.', array['Step one foot back and across behind the other, hips facing forward','Lower until the front thigh is near parallel; front knee tracks the toes','Drive through the front heel to return to standing','Keep the torso tall; control the crossover — do not let the knee cave in']::text[], 'dumbbell'),
('db-sumo-squat', 'DB Sumo Squat', 'hotel_gym', 'compound', array['glute_max','adductor']::text[], array['quad_rectus_femoris','quad_vastus']::text[], array['glutes','lower_body']::text[], null, 'reps', null, null, 'The wide stance and turned-out toes shift the squat toward the glutes and inner-thigh adductors — a hip- and adductor-biased pattern that a narrow squat misses, loaded simply with a single dumbbell held between the legs.', array['Feet wider than shoulders, toes turned out ~30°','Hold one dumbbell between the legs, chest tall','Sit straight down, driving the knees out over the toes','Squeeze the glutes hard to stand; keep the torso upright']::text[], 'dumbbell'),
('frog-pump', 'Frog Pump', 'home', 'isolation', array['glute_max']::text[], array[]::text[], array['glutes','lower_body']::text[], null, 'reps', null, null, 'The soles-together, knees-out position pre-shortens the glutes so every rep peaks in deep hip extension with minimal quad or hamstring contribution — a high-rep glute burnout that isolates the glute max better than most bridges, no equipment needed.', array['Lie on your back, soles of the feet together, knees dropped wide','Drive the hips up by squeezing the glutes — heels stay together','Pause and squeeze hard at the top','Lower with control; keep the reps quick and continuous for the pump']::text[], 'bodyweight'),
('standing-calf-raise', 'Standing Calf Raise', 'full_gym', 'isolation', array['gastrocnemius','calf']::text[], array[]::text[], array['lower_body']::text[], null, 'reps', null, 'gwLzBJYoWlA', 'The gastrocnemius is bi-articular — it crosses both the ankle and knee. Straight-knee position fully recruits both heads. This is the primary exercise for calf mass.', array['Full stretch at the bottom: heel below platform level','Rise to maximum height on tiptoe','Pause one count at the top — no bouncing','Slow descent — 3-count lower']::text[], 'machine'),
('seated-calf-raise', 'Seated Calf Raise', 'full_gym', 'isolation', array['soleus','calf']::text[], array[]::text[], array['lower_body']::text[], null, 'reps', null, 'JbyjNymZsfQ', 'Bent-knee position slackens the gastrocnemius, isolating the soleus underneath. The soleus is slow-twitch dominant — it responds best to high reps (15–25). A thick soleus widens the calf visually from all angles.', array['Pad just above the knee, not on the kneecap','Full stretch at the bottom','Rise to maximum height; pause one count','High reps are more effective here than heavy weight']::text[], 'machine'),
('leg-press-calf-raise', 'Leg Press Calf Raise', 'full_gym', 'isolation', array['gastrocnemius','calf']::text[], array[]::text[], array['lower_body']::text[], null, 'reps', null, null, 'Allows very heavy plantarflexion loading with no spinal compression. Fixed platform provides consistent ROM. Useful when the standing calf raise machine is occupied.', array['Only toes and ball of foot on the platform — heels hang off','Press to full plantarflexion (tiptoe position)','Lower until heels are below the platform level','High reps, slow tempo — calves are built with volume']::text[], 'machine'),
('single-leg-calf-raise', 'Single-Leg Calf Raise', 'home', 'isolation', array['gastrocnemius','calf']::text[], array[]::text[], array['lower_body']::text[], null, 'reps', null, null, 'Doubles the eccentric load versus bilateral — providing 2× the resistance with bodyweight alone. Progressed by adding a loaded backpack, holding a dumbbell, or increasing tempo.', array['Stand on one foot on a step edge — heel hanging off','Lower to full stretch position','Rise to max height; single-leg focus prevents compensation','If too easy, add load; if too hard, hold a wall lightly']::text[], 'bodyweight'),
('db-standing-calf-raise', 'DB Standing Calf Raise', 'hotel_gym', 'isolation', array['gastrocnemius','calf']::text[], array[]::text[], array['lower_body']::text[], null, 'reps', null, null, 'Brings external load to the straight-knee calf raise without a machine — a dumbbell in each hand plus a step edge fully recruits both gastrocnemius heads. A simple free-weight answer to the standing calf machine.', array['Stand tall on a step edge, balls of feet on, heels hanging','Hold a dumbbell in each hand, arms relaxed at sides','Full stretch at the bottom, then rise to maximum tiptoe height','Pause one count at the top; 3-count lower — no bouncing']::text[], 'dumbbell'),
('smith-machine-calf-raise', 'Smith Machine Calf Raise', 'full_gym', 'isolation', array['gastrocnemius','calf']::text[], array[]::text[], array['lower_body']::text[], null, 'reps', null, null, 'The fixed Smith bar lets a lifter load standing calf raises heavily and safely with just a block under the toes — a straight-knee plantarflexion that fully recruits both gastrocnemius heads when a dedicated calf machine is unavailable.', array['Balls of the feet on a block or plate, bar across the upper traps','Full stretch at the bottom — heels drop below the block','Rise to maximum height on the toes; pause one count','Slow 3-count descent — build calves with controlled volume']::text[], 'machine'),
('dead-bug', 'Dead Bug', 'home', 'core', array['transverse_abdominis','rectus_abdominis']::text[], array['psoas','erector_spinae']::text[], array['core','full_body']::text[], null, 'reps', null, null, 'McGill-approved anti-extension movement. Forces the core to resist spinal extension while contralateral limbs move — exactly what the core does during every compound lift. Zero spinal shear. Safest core exercise for any lower back history.', array['Press lower back FLAT into floor throughout — this is the whole exercise','Move opposite arm and leg simultaneously','Breathe out as you lower the limbs','If the back lifts, the set is over']::text[], 'bodyweight'),
('plank', 'Plank', 'home', 'core', array['transverse_abdominis','rectus_abdominis']::text[], array['erector_spinae','glute_max']::text[], array['core']::text[], null, 'sec', 60, 'pSHjTRCQxIw', 'Anti-extension core training — builds the ability to resist spinal extension under load, exactly the demand during heavy squats and deadlifts.', array['Forearms on floor, elbows under shoulders','Body in a straight line from head to heels','Squeeze glutes and abs simultaneously','Breathe normally — if you cannot breathe, reduce the duration']::text[], 'bodyweight'),
('side-plank', 'Side Plank', 'home', 'core', array['quadratus_lumborum','oblique_external','glute_medius']::text[], array[]::text[], array['core']::text[], null, 'sec', 45, null, 'McGill Big 3 staple — the only exercise that loads the lateral core (QL and obliques) without spinal compression. QL weakness is the most overlooked contributor to lower back pain.', array['Elbow directly under shoulder','Hips stacked — do not let the top hip rotate forward','Straight line from head through feet','Keep neck neutral — do not let the head drop']::text[], 'bodyweight'),
('bird-dog', 'Bird Dog', 'home', 'core', array['erector_spinae','glute_max','transverse_abdominis']::text[], array[]::text[], array['core','full_body']::text[], null, 'reps', null, null, 'McGill Big 3 exercise — simultaneously trains lumbar extensors, glute max, and contralateral rotator coordination without any spinal compression.', array['Start on all fours, spine neutral','Extend opposite arm and leg simultaneously','Do not let the hip rotate or the lower back arch','Pause at full extension for two counts; reset with control']::text[], 'bodyweight'),
('ab-wheel-rollout', 'Ab Wheel Rollout', 'home', 'core', array['rectus_abdominis','transverse_abdominis']::text[], array['lat_dorsi','hip_flexor']::text[], array['core','upper_body']::text[], null, 'reps', null, null, 'The highest rectus abdominis activation exercise that exists — significantly higher than crunches, planks, or leg raises. Start from the knees; progress to standing rollouts.', array['Start on knees; wheel directly under shoulders','Roll out keeping hips down — do not let the back arch','Roll to maximum range before your back starts to arch','Pull back in with lats AND abs — both are working']::text[], 'bodyweight'),
('cable-crunch', 'Cable Crunch', 'full_gym', 'core', array['rectus_abdominis']::text[], array[]::text[], array['core']::text[], null, 'reps', null, null, 'The only weighted abs exercise with constant resistance through the full ROM. Allows progressive overload on the rectus abdominis — you can add load every week.', array['Kneel facing the cable, hands behind your neck (not pulling)','Crunch by flexing the spine — do not hip hinge','Round the upper back; bring sternum toward the pelvis','Slow return — the eccentric phase is 70% of the benefit']::text[], 'cable'),
('hanging-knee-raise', 'Hanging Knee Raise', 'hotel_gym', 'core', array['rectus_abdominis','hip_flexor']::text[], array['transverse_abdominis']::text[], array['core']::text[], null, 'reps', null, null, 'The hanging position also trains grip and shoulder girdle stability. Progressed from knee raise to straight-leg raise to full toes-to-bar. A pull-up bar is sufficient — no dedicated equipment needed.', array['Dead hang; do not swing','Draw knees to chest by curling the pelvis — not just lifting the legs','Lower with control — do not drop','Advanced: straighten legs for a dramatically harder version']::text[], 'bodyweight'),
('reverse-crunch', 'Reverse Crunch', 'home', 'core', array['rectus_abdominis_lower']::text[], array['transverse_abdominis']::text[], array['core']::text[], null, 'reps', null, null, 'One of very few exercises that specifically targets the lower rectus abdominis fibres. The curling pelvis motion (posterior pelvic tilt) is the key mechanic that distinguishes it from basic leg raises.', array['Lie flat; curl the knees to the chest by tilting the pelvis — not just lifting the knees','Lower back should press into the floor throughout','Slow and controlled — not momentum-based','Progress by adding a pause at peak tilt']::text[], 'bodyweight'),
('pallof-press', 'Pallof Press', 'full_gym', 'core', array['transverse_abdominis','oblique_internal','oblique_external']::text[], array[]::text[], array['core']::text[], null, 'reps', null, null, 'Anti-rotation core exercise — the cable pulls the body sideways and the core resists that rotation. Exactly the demand placed on the core in rotational sports and under asymmetric loads.', array['Cable at chest height; stand perpendicular to it','Press hands straight out from chest; resist the lateral pull','Keep hips square — the fight is between the cable and your core','Hold extended position for two counts; controlled throughout']::text[], 'cable'),
('russian-twist', 'Russian Twist', 'home', 'core', array['oblique_external','oblique_internal']::text[], array[]::text[], array['core']::text[], null, 'reps', null, null, 'Trains the obliques through rotation — the pattern that generates punching power, throwing velocity, and athletic rotation. Progressed with a medicine ball, weight plate, or dumbbell.', array['Sit at 45° with feet elevated (harder) or on floor (easier)','Rotate from the torso, not just the arms','Touch the floor beside each hip each rep','Brace the core throughout — do not let the spine collapse']::text[], 'bodyweight'),
('dragon-flag', 'Dragon Flag', 'hotel_gym', 'core', array['rectus_abdominis']::text[], array['transverse_abdominis','hip_flexor']::text[], array['core','full_body']::text[], null, 'reps', null, null, 'The hardest bodyweight anti-extension exercise — the whole body is held rigid as a lever while the abs resist gravity trying to pull the spine into extension. Popularised by Bruce Lee, it produces among the highest rectus abdominis demands possible with no equipment beyond something to hold.', array['Lie on a bench or floor; grip a solid post behind the head','Brace and lift the whole body toward vertical, weight on the upper back','Lower the straight, rigid body as one unit — no bend at the hips','Keep the lower back from arching; regress by bending the knees']::text[], 'bodyweight'),
('hanging-leg-raise', 'Hanging Leg Raise', 'hotel_gym', 'core', array['rectus_abdominis_lower','hip_flexor']::text[], array['transverse_abdominis']::text[], array['core']::text[], null, 'reps', null, null, 'The straight-leg progression of the hanging knee raise — the longer lever dramatically increases the load on the lower rectus abdominis, while the dead hang trains grip and shoulder stability. The benchmark hanging ab movement on the way to toes-to-bar.', array['Dead hang from a bar, no swinging','Raise straight legs by curling the pelvis up — not just lifting the legs','Bring the legs to at least parallel; higher recruits more lower abs','Lower under control; keep the movement strict, not momentum-driven']::text[], 'bodyweight'),
('weighted-decline-sit-up', 'Weighted Decline Sit-Up', 'hotel_gym', 'core', array['rectus_abdominis']::text[], array['hip_flexor','oblique_external']::text[], array['core']::text[], null, 'reps', null, null, 'The decline angle lengthens the range of the sit-up and holding a plate or dumbbell adds progressive load — one of the few ways to train the full rectus abdominis with heavy, trackable resistance rather than endless bodyweight reps.', array['Anchor the feet on a decline bench, hold a plate on the chest','Curl up by flexing the spine — round the back off the bench segment by segment','Do not yank with the hip flexors; the abs initiate','Lower under control through the full range; add load as it gets easy']::text[], 'dumbbell'),
('cable-woodchopper', 'Cable Woodchopper', 'full_gym', 'core', array['oblique_external','oblique_internal']::text[], array['transverse_abdominis']::text[], array['core']::text[], null, 'reps', null, null, 'A loaded rotational chop trains the obliques through the exact diagonal power pattern used in throwing, swinging, and rotating — with constant cable tension the whole way. Progressive resistance for rotational strength that the bodyweight Russian twist cannot match.', array['Set the pulley high; grip the handle with both hands','Rotate down and across the body to the opposite hip — pivot the back foot','Drive the motion from the trunk, not the arms','Control the return; keep the arms fairly straight throughout']::text[], 'cable'),
('machine-ab-crunch', 'Machine Ab Crunch', 'full_gym', 'core', array['rectus_abdominis']::text[], array['oblique_external']::text[], array['core']::text[], null, 'reps', null, null, 'The ab crunch machine adds selectable, progressive resistance to spinal flexion through a guided path — letting a lifter overload the rectus abdominis in small increments exactly like any other muscle, safely and to failure. Weighted, trackable ab training in a fixed groove.', array['Set the seat and pad so the resistance sits across the chest/shoulders','Crunch by rounding the spine — bring the sternum toward the pelvis','Do not hinge at the hips; the movement is spinal flexion','Control the eccentric all the way back — that phase drives most of the growth']::text[], 'machine'),
('hollow-body-hold', 'Hollow Body Hold', 'home', 'core', array['rectus_abdominis','transverse_abdominis']::text[], array['hip_flexor']::text[], array['core']::text[], null, 'sec', 30, null, 'The gymnastics foundation for anti-extension strength — pressing the lower back flat while holding the arms and legs off the ground trains the abs to hold a braced, neutral spine under a long lever. Directly transfers to the midline stability every heavy lift demands.', array['Lie supine; press the lower back FLAT into the floor — this never releases','Lift the shoulders and legs off the floor into a shallow banana shape','Arms overhead by the ears; legs straight — the lower the harder','If the back lifts off the floor, raise the arms/legs higher and rebuild']::text[], 'bodyweight'),
('standing-cable-oblique-crunch', 'Standing Cable Oblique Crunch', 'full_gym', 'core', array['oblique_external','oblique_internal']::text[], array['quadratus_lumborum']::text[], array['core']::text[], null, 'reps', null, null, 'A loaded lateral-flexion crunch that trains the obliques and QL through the side-bending pattern with progressive cable resistance — the frontal-plane counterpart to the cable crunch. Builds the lateral core that stabilises the spine under uneven loads like suitcase carries.', array['Stand side-on to a high pulley, handle in the near hand','Crunch the torso down toward the working-side hip — bend at the waist','Keep the hips still; the motion is pure lateral flexion','Resist the cable back up under control; finish all reps, then switch sides']::text[], 'cable'),
('landmine-rotation', 'Landmine Rotation', 'full_gym', 'core', array['oblique_external','oblique_internal']::text[], array['transverse_abdominis','anterior_delt']::text[], array['core']::text[], null, 'reps', null, null, 'Sweeping a landmine bar in an arc from hip to hip trains rotation and anti-rotation together under a load that scales indefinitely — building trunk rotational power through a long, controlled range that a barbell landmine makes easy to progress.', array['Hold the barbell end at full arm extension in front of the chest','Rotate the bar in an arc down to one hip, pivoting the feet','Drive the rotation from the trunk, arms fairly straight','Control the arc across to the other hip — do not let it free-fall']::text[], 'barbell'),
('toes-to-bar', 'Toes-to-Bar', 'hotel_gym', 'core', array['rectus_abdominis_lower','hip_flexor']::text[], array['lat_dorsi','transverse_abdominis']::text[], array['core']::text[], null, 'reps', null, null, 'The full-range endpoint of hanging ab work — bringing the toes all the way to the bar demands maximal lower-ab and hip-flexor strength plus lat engagement to control the swing. The benchmark advanced hanging core movement.', array['Dead hang; engage the lats to stop any swing','Curl the pelvis and drive the straight legs all the way up to the bar','Control the descent — no kipping or momentum','Regress to knee raises or leg raises until the strength is there']::text[], 'bodyweight'),
('bicycle-crunch', 'Bicycle Crunch', 'home', 'core', array['rectus_abdominis','oblique_external']::text[], array['oblique_internal']::text[], array['core']::text[], null, 'reps', null, null, 'Consistently one of the highest EMG-ranked ab exercises — the pedaling twist trains the rectus abdominis and obliques together through flexion plus rotation, with zero equipment. A staple for combined ab and oblique work anywhere.', array['Lie back, hands lightly behind the head, shoulders off the floor','Bring one elbow toward the opposite knee as that leg drives in','Extend the other leg straight without letting it touch down','Rotate from the torso, not the neck; move slowly and with control']::text[], 'bodyweight'),
('v-up', 'V-Up', 'home', 'core', array['rectus_abdominis']::text[], array['hip_flexor']::text[], array['core']::text[], null, 'reps', null, null, 'Lifting the straight arms and legs to meet over the hips folds the body at the abs, contracting the full rectus abdominis top-and-bottom simultaneously. A no-equipment progression up from the crunch that trains the whole ab wall in one movement.', array['Lie flat, arms extended overhead, legs straight','Lift the arms and legs together to touch over the hips in a V','Keep both the arms and legs straight — hinge only at the hips','Lower under control without letting the feet or hands touch down']::text[], 'bodyweight'),
('standing-cable-crunch', 'Standing Cable Crunch', 'full_gym', 'core', array['rectus_abdominis']::text[], array['oblique_external']::text[], array['core']::text[], null, 'reps', null, null, 'A standing, weighted spinal-flexion crunch against a high cable — constant progressive resistance on the rectus abdominis without kneeling, convenient to superset between other standing lifts. Loads the abs like any other muscle for real overload.', array['Face away from a high pulley, rope held at the collarbones','Crunch down by rounding the spine — bring the ribs toward the pelvis','Keep the hips fixed; the motion is spinal flexion, not a hip hinge','Resist the cable back up slowly to a full stretch']::text[], 'cable'),
('copenhagen-plank', 'Copenhagen Plank', 'home', 'core', array['adductor','oblique_external']::text[], array['transverse_abdominis']::text[], array['core']::text[], null, 'sec', 30, null, 'A side plank with the top leg on a bench that loads the adductors isometrically while the lateral core holds the hips level — building groin strength that dramatically lowers adductor-strain risk, alongside the obliques and QL.', array['Side plank position, elbow under the shoulder','Rest the top (upper) leg on a bench, bottom leg hanging or lifted','Lift the hips so the body is a straight line — squeeze the top inner thigh','Hold for time; regress by resting the bottom knee, progress by holding the bottom leg up']::text[], 'bodyweight'),
('hanging-oblique-raise', 'Hanging Oblique Raise', 'hotel_gym', 'core', array['oblique_external','oblique_internal']::text[], array['rectus_abdominis_lower','hip_flexor']::text[], array['core']::text[], null, 'reps', null, null, 'Raising the knees to one side while hanging adds rotation and lateral flexion to the knee raise — loading the obliques through a long range under the same grip and shoulder-stability demand as other hanging ab work.', array['Dead hang from a bar, no swinging','Curl the knees up and toward one side, twisting at the waist','Squeeze the obliques at the top; control the return','Alternate sides evenly; keep the movement strict, not swung']::text[], 'bodyweight'),
('jumping-jacks', 'Jumping Jacks', 'home', 'cardio', array['full_body','glute_max']::text[], array['calf']::text[], array['lower_body','full_body']::text[], null, 'reps', null, null, 'Zero-equipment full-body cardio — elevates heart rate through continuous total-body movement when no machine is available.', array['Land softly, knees soft on impact','Full arm extension overhead each rep','Steady rhythm — this is Zone 2, not a sprint','20+ min continuous, or interval with High Knees']::text[], 'bodyweight'),
('high-knees', 'High Knees', 'home', 'cardio', array['quad','glute_max','hamstring']::text[], array[]::text[], array['lower_body','full_body']::text[], null, 'reps', null, null, 'Zero-equipment hip-flexor-driven cardio — the running-in-place pattern trains the same quad/glute/hamstring cycling action as treadmill or bike work with no equipment required.', array['Drive knees to hip height, quick cadence','Land on the balls of the feet','Pump the arms to maintain rhythm','Moderate, sustainable pace for Zone 2 duration']::text[], 'bodyweight'),
('incline-treadmill', 'Incline Treadmill', 'full_gym', 'cardio', array['glute_max','hamstring','calf']::text[], array[]::text[], array['lower_body','full_body']::text[], null, 'reps', null, null, 'Zone 2 cardio at 10–15% incline elevates glute and hamstring activation dramatically versus flat walking. Low impact preserves recovery capacity while still stimulating aerobic adaptation.', array['Incline 10–15%, pace 3–3.5 mph for Zone 2','Do not hold the rails — swing the arms naturally','Heart rate 60–70% of max for fat oxidation zone','Duration 20–25 min: long enough for mitochondrial adaptation']::text[], 'machine'),
('stationary-bike', 'Stationary Bike', 'hotel_gym', 'cardio', array['quad','glute_max','hamstring']::text[], array[]::text[], array['lower_body']::text[], null, 'reps', null, null, 'Zero impact on joints — ideal when legs are sore from squats and lunges. Cycle ergometers produce excellent Zone 2 cardio data in sports science research. Widely available in most gyms.', array['Seat height: slight knee bend at bottom of pedal stroke','Moderate resistance — not easy spinning, not grinding','Heart rate 60–70% of max','20 minutes minimum for meaningful aerobic benefit']::text[], 'machine'),
('elliptical', 'Elliptical', 'hotel_gym', 'cardio', array['quad','glute_max','hamstring']::text[], array[]::text[], array['lower_body','full_body']::text[], null, 'reps', null, null, 'Mimics a running stride with zero impact. The arm poles add upper body engagement and increase total energy expenditure by 10–15% versus leg-only use.', array['Use the arm poles — they increase caloric burn and stabilise the trunk','Do not lean on the machine — maintain your own posture','Moderate resistance and pace — this is not a sprint','Zone 2 heart rate target: 60–70% of max']::text[], 'machine'),
('rower', 'Rower', 'full_gym', 'cardio', array['lat_dorsi','quad','glute_max']::text[], array['bicep','hamstring','erector_spinae']::text[], array['full_body','back','lower_body']::text[], null, 'reps', null, null, 'Engages 86% of muscle mass — more than any other cardio machine. The sequencing of leg drive → hip hinge → arm pull mirrors the deadlift pattern, making it the most functional cardio for strength programs.', array['Drive order: LEGS → LEAN BACK → ARMS; reverse on recovery','Drive hard through the heels at the catch','Do not open the hips until the handle passes the knees','Damper setting 4–6 for aerobic work; higher is not better']::text[], 'machine'),
('kb-swing', 'KB Swing', 'hotel_gym', 'cardio', array['glute_max','hamstring']::text[], array['lat_dorsi','erector_spinae','core']::text[], array['glutes','lower_body','full_body']::text[], null, 'reps', null, 'sSNGZzfMqE8', 'Trains hip extension power and cardiovascular conditioning simultaneously. At high rep counts the metabolic demand rivals sprinting. Posterior chain loading makes this cardio that also builds muscle.', array['Hip hinge — this is NOT a squat; hike the bell back between legs','Drive hips forward explosively; the bell floats to chest height by momentum','Squeeze glutes hard at the top of every rep','Re-hinge immediately on the way down — do not squat to receive the bell']::text[], 'dumbbell'),
('band-external-rotation', 'Band External Rotation', 'home', 'isolation', array['external_rotator']::text[], array[]::text[], array['shoulders','upper_body']::text[], null, 'reps', null, null, 'Trains external rotation at the shoulder joint itself rather than at the shoulder blade. Pull-aparts and face pulls retract the scapula; this rotates the humerus inside the socket, which is a different job and the one the bank currently has no dedicated entry for. Band tension stays constant through a range where a dumbbell gives almost nothing at the start, which is why rehab-side coaching keeps it at the front of shoulder work. The source is explicit that the upper arm must stay pinned at the side — a rolled towel under the arm is its recommended fix — because letting the elbow drift away converts the movement into something that is no longer pure external rotation.', array['Anchor the band at about elbow height and stand side-on, working arm on the outside','Elbow bent to 90 degrees and tucked at your side; a rolled towel under the arm keeps it there','Rotate the forearm away from your stomach — the upper arm does not move','Control the band all the way back; do not let it snap your hand to your belly']::text[], 'band'),
('lateral-step-down', 'Lateral Step-Down', 'home', 'compound', array['quad_rectus_femoris','quad_vastus_lateralis']::text[], array['glute_max','glute_medius']::text[], array['quads','glutes','lower_body']::text[], null, 'reps', null, null, 'Stepping down off a low box loads the standing leg while the knee travels further into flexion than a step-up allows, and that extra travel is the point rather than a side effect. For Tandem this is a zero-equipment single-leg quad builder that doubles as knee-health work for runners and hikers, at a tier where the library currently has no eccentric-emphasis single-leg option at all.', array['Stand on a 6-7 inch step with all the weight through the working leg','Reach the free leg out to the side and tap the heel down - do not push off it','Let the working knee travel forward; that range is what you are training','Slow and controlled on the way down; hold a wall or rail if balance is the limiter']::text[], 'bodyweight'),
('band-row', 'Band Row', 'home', 'compound', array['lat_dorsi','rhomboid']::text[], array['bicep','posterior_delt']::text[], array['back','pull','upper_body']::text[], null, 'reps', null, null, 'The first band compound in the bank and the only home-tier pull whose resistance can be dialed down. Table Inverted Row loads by body angle, which sets a hard floor a deconditioned or rehabbing lifter may not clear; a band starts near zero and scales by band choice and anchor distance. Horizontal pulling is also the least shoulder-demanding pull pattern, so it is the right entry point before any overhead work.', array['Anchor the band at chest height to a sturdy object or door','Sit or stand tall, arms extended, slight tension at the start','Start the pull with the shoulder blade, then let the elbow follow','Drive elbows back toward the hips, not flared wide','Control the return all the way out - keep tension the whole range']::text[], 'band'),
('mcgill-curl-up', 'McGill Curl-Up', 'home', 'core', array['rectus_abdominis']::text[], array['oblique_external','transverse_abdominis']::text[], array['core']::text[], null, 'sec', 10, null, 'The third McGill Big 3 movement, and the one the bank is missing. Trains the anterior core to hold a braced trunk while the hands stay under the small of the back to preserve its natural inward curve, so the abs work hard without the repeated spinal flexion a sit-up demands. Side Plank and Bird Dog both already name the McGill Big 3 in their own rationale; this completes the set.', array['Lie on your back, one knee bent with that foot flat, the other leg straight','Slide both hands palm-down under the small of your back and keep its natural arch - do not press the back flat','Brace the abs, then lift head and shoulders as one rigid unit only an inch or two; chin does not tuck, neck does not crane','Hold ten seconds breathing normally, lower with control, and add repetitions rather than a longer hold as it gets easier']::text[], 'bodyweight')
on conflict (slug) do update set
  name = excluded.name,
  tier = excluded.tier,
  category = excluded.category,
  muscle_primary = excluded.muscle_primary,
  muscle_secondary = excluded.muscle_secondary,
  emphasis = excluded.emphasis,
  one_rm_factor = excluded.one_rm_factor,
  unit = excluded.unit,
  secs = excluded.secs,
  video_id = excluded.video_id,
  why = excluded.why,
  cues = excluded.cues,
  equipment = excluded.equipment;
